with base_sequences as (
  select category, coalesce(max(sequence), 0) as value
  from public.quiz_questions
  where category in ('pedagogica', 'razonamiento')
  group by category
),
blocks (block_id, block_range, category, topic, situation) as (
  values
    ('elkin-situacion-1', '1-25', 'pedagogica', 'Convivencia escolar y rutas de atencion', 'Situación 1. Entre el silencio, la exposición digital y la protección de derechos La Institución Educativa Rural Nuevo Horizonte atiende estudiantes de preescolar, básica y media en una zona donde confluyen familias campesinas, trabajadores de una empresa minera cercana, pequeños comerciantes y población que ha llegado recientemente desde otros municipios. Aunque la institución cuenta con un manual de convivencia, este no ha sido actualizado durante los últimos tres años. En sus apartados sobre conflictos escolares se mencionan sanciones como llamados de atención, anotaciones, suspensiones y cancelación de matrícula, pero no se diferencian con claridad los conflictos ocasionales, las agresiones repetidas, el acoso escolar, el ciberacoso ni las situaciones que podrían constituir una conducta delictiva. En el grado octavo B estudia Valeria, una adolescente de trece años que ingresó a la institución al comenzar el año escolar. Su familia se trasladó desde una vereda distante y se dedica a la producción artesanal de alimentos. Valeria tiene un acento diferente al de la mayoría de sus compañeros, suele participar poco en clase y presenta buen desempeño académico. Durante las primeras semanas, la directora de grupo observó que algunos estudiantes imitaban la forma de hablar de Valeria y se reían cuando ella participaba. La docente consideró que eran bromas propias de la edad y les recomendó verbalmente que fueran respetuosos, pero no registró lo sucedido ni indagó si las conductas eran reiteradas. Semanas después, Samuel, Nicolás y otros estudiantes crearon un grupo de mensajería denominado “Octavo sin filtro”. Aunque el grupo no había sido creado por la institución, participaban en él casi todos los estudiantes del curso. Allí comenzaron a publicar fotografías de actividades escolares, comentarios sobre docentes y bromas entre compañeros. Una tarde, Samuel tomó una fotografía de Valeria durante una exposición, la editó agregándole imágenes de animales y escribió una frase relacionada con su acento y el trabajo de su familia. La publicación recibió numerosas reacciones. Algunos estudiantes respondieron con emoticones de risa, otros enviaron mensajes similares y varios guardaron silencio. Durante las tres semanas siguientes se publicaron nuevos montajes, notas de voz y comentarios sobre Valeria. En varias ocasiones la retiraron del grupo y luego la agregaron nuevamente para que pudiera observar las publicaciones. También difundieron una encuesta en la que preguntaban quién era “la estudiante más rara del curso”. Valeria obtuvo la mayoría de los votos. Valeria no informó inicialmente a los docentes porque temía que la llamaran “acusona”. Sin embargo, empezó a faltar a clases, dejó de participar y pidió a su madre que la trasladara de institución. En casa manifestó dolores de estómago, dificultades para dormir y temor de revisar su teléfono. Un lunes, durante una clase, Samuel escondió el cuaderno de Valeria y lo entregó a otros compañeros. Cuando ella intentó recuperarlo, tomó la gorra de Samuel y le dijo que no se la devolvería hasta que apareciera su cuaderno. Samuel respondió empujándola contra un pupitre. Valeria presentó un hematoma leve en el brazo, pero el servicio de salud determinó que no requería incapacidad. Dos estudiantes grabaron el momento. En el video solo se observaba a Valeria tomando la gorra y a Samuel empujándola; no aparecía el momento en el que habían escondido el cuaderno. El video fue difundido con el mensaje: “Valeria provoca a Samuel y después se hace la víctima”. La directora de grupo informó al coordinador, quien reunió inmediatamente a Valeria y Samuel en la oficina. Les pidió que explicaran lo sucedido frente a frente y propuso llevarlos al salón para que ofrecieran disculpas públicas. El coordinador consideraba que presentar el caso ante el curso permitiría “cerrar el problema rápidamente”. La docente orientadora intervino y manifestó que era necesario escuchar a los estudiantes por separado, garantizar la seguridad de Valeria, valorar su estado físico y emocional, conservar los mensajes y videos disponibles, identificar la secuencia completa de los hechos e informar al rector. También señaló que no debía exponerse públicamente a ninguno de los estudiantes ni obligarlos a participar inmediatamente en una confrontación. La madre de Valeria llegó a la institución y exigió la expulsión definitiva de Samuel. Afirmó que publicaría en redes sociales los nombres y fotografías de todos los estudiantes involucrados si el colegio no actuaba. Por su parte, el padre de Samuel sostuvo que se trataba de “una pelea entre dos estudiantes” porque Valeria había tomado primero la gorra de su hijo. También indicó que los mensajes del grupo virtual habían sido eliminados y que, por tanto, no existían pruebas suficientes. Al revisar el caso, la docente orientadora encontró capturas de pantalla, testimonios coincidentes y mensajes recuperados por varios estudiantes. Identificó que las publicaciones se habían repetido durante varias semanas, que Valeria se encontraba en una situación de desventaja frente al grupo y que las conductas habían afectado su asistencia, su salud emocional y su participación escolar. El Comité Escolar de Convivencia fue convocado de manera extraordinaria. Durante la reunión surgieron distintas posiciones. Algunos docentes propusieron suspender a Samuel durante cinco días y dar por terminado el caso. Otros sugirieron realizar una campaña general sobre el respeto, sin mencionar lo ocurrido. La docente orientadora planteó que las actuaciones debían incluir protección inmediata, atención a la estudiante afectada, intervención pedagógica con quienes participaron, trabajo con los observadores, vinculación de las familias, seguimiento periódico y revisión de las condiciones institucionales que permitieron la repetición de las agresiones. El rector reconoció que la institución no contaba con un procedimiento claro para atender agresiones digitales. También admitió que varios docentes confundían los conflictos ocasionales con el acoso escolar y que las anotaciones realizadas en los observadores de los estudiantes no incluían información suficiente sobre las actuaciones, los responsables, los compromisos ni el seguimiento. Mientras la docente orientadora entrevistaba individualmente a algunos estudiantes, Juliana, compañera de Valeria, pidió hablar en privado. La adolescente relató que un adulto contratado para conducir una de las rutas escolares le había enviado mensajes en los que comentaba su cuerpo, le pedía fotografías íntimas y le ofrecía regalos a cambio de encontrarse a solas. Juliana mostró varios mensajes y dijo que el hombre le había pedido mantenerlos en secreto. Juliana afirmó que no había ocurrido contacto físico, pero manifestó temor porque debía utilizar la misma ruta para regresar a casa. También pidió a la orientadora que no le contara a nadie, pues creía que su tía, con quien vivía, podía culparla por haber respondido inicialmente algunos mensajes. La docente orientadora explicó que escucharía su relato con respeto y manejaría la información de manera reservada, pero que no podía prometer silencio absoluto cuando existía un riesgo para su integridad. Le indicó que solo compartiría la información con las personas y entidades necesarias para protegerla. Al conocer la situación, el rector propuso citar primero al conductor para escuchar su versión y realizar una investigación interna antes de informar a otras entidades. Argumentó que era necesario evitar acusaciones injustas y proteger el nombre de la institución. La orientadora señaló que la prioridad debía ser impedir que Juliana continuara expuesta al adulto, conservar las evidencias, informar a las autoridades competentes y evitar que la estudiante tuviera que repetir innecesariamente su relato. La empresa encargada del transporte fue informada de que el adulto no debía tener contacto con Juliana mientras se desarrollaban las actuaciones correspondientes. La institución organizó temporalmente otra forma de transporte para la estudiante y acordó acompañamiento emocional. En el caso de Valeria, se estableció un plan de protección para su regreso a clases. Se designó una docente de confianza, se acordaron espacios de acompañamiento, se reorganizaron temporalmente algunos puestos del salón y se pidió a los docentes observar posibles acciones de retaliación. También se inició un proceso pedagógico con Samuel y con los demás estudiantes que participaron o reforzaron las publicaciones. No obstante, dos semanas después, Valeria informó que varios compañeros habían dejado de hablarle y que algunos la llamaban “sapa” en los pasillos. Samuel había cumplido con las actividades escritas asignadas, pero sostenía que todo había sido “una broma exagerada por los adultos”. Los estudiantes que habían reaccionado con emoticones afirmaban que no habían creado las publicaciones y que, por tanto, no tenían responsabilidad. El Comité Escolar de Convivencia concluyó que no bastaba con eliminar las publicaciones ni aplicar una sanción aislada. Propuso revisar el manual de convivencia, fortalecer la formación docente, establecer protocolos para situaciones digitales, promover la participación estudiantil, formar a las familias en ciudadanía digital y crear indicadores que permitieran verificar si las agresiones disminuían, si las estudiantes se sentían seguras y si los acuerdos se cumplían.'),
    ('elkin-situacion-2', '26-50', 'pedagogica', 'Inclusion educativa y evaluacion', 'A. Concentrar los esfuerzos en sancionar con mayor firmeza, porque la claridad de las consecuencias evita que las situaciones vuelvan a ocurrir. B. Delegar los casos complejos en la docente orientadora, quien posee la formación especializada para atender las vulneraciones escolares. C. Articular promoción, prevención, atención y seguimiento, fortaleciendo capacidades institucionales y coordinando la protección con otros actores. Pregunta 25 El plan institucional más sólido frente a la situación descrita sería aquel que: A. Mantenga la protección individual, active las instancias correspondientes, intervenga pedagógicamente con el grupo, fortalezca el manual, capacite al personal y evalúe resultados mediante seguimiento continuo. B. Resuelva cada caso mediante acuerdos familiares, sanciones proporcionales y campañas generales, evitando involucrar actores externos mientras existan posibilidades de solución institucional. C. Priorice la actualización documental, la aplicación uniforme de sanciones y la centralización de los casos en el Comité Escolar de Convivencia para asegurar decisiones consistentes. Situación 2. Evaluar para aprender sin convertir las diferencias en barreras La siguiente situación integra el marco vigente sobre educación inclusiva, ajustes razonables, valoración integral, promoción escolar y participación de la comunidad educativa. (Función Pública) La Institución Educativa Técnica Agroambiental La Esperanza está ubicada en un municipio intermedio de Colombia y atiende aproximadamente a novecientos estudiantes provenientes del casco urbano, veredas cercanas y familias que trabajan en actividades agrícolas, comerciales y de transporte. La institución ofrece educación desde preescolar hasta grado undécimo y cuenta con una sede principal de tres pisos, una biblioteca, un laboratorio de ciencias, una sala de informática y algunos espacios deportivos. Durante los últimos años, la institución ha matriculado a varios estudiantes que requieren apoyos específicos para aprender y participar. Sin embargo, sus prácticas pedagógicas y evaluativas todavía se encuentran centradas principalmente en clases magistrales, talleres escritos, exámenes cronometrados y calificaciones obtenidas mediante promedios aritméticos. El sistema institucional de evaluación establece que el 60 % de la valoración de cada periodo corresponde a pruebas escritas, el 30 % a trabajos y tareas, y el 10 % a aspectos personales y sociales. El documento institucional también señala que un estudiante reprueba el año cuando obtiene desempeño bajo en tres o más áreas o cuando supera el 15 % de inasistencia. Aunque se mencionan actividades de recuperación, estas se realizan principalmente durante la última semana de cada periodo. El sistema no incluye orientaciones claras sobre flexibilización curricular, accesibilidad, ajustes en los instrumentos de evaluación, diversidad de formas para demostrar los aprendizajes ni procedimientos específicos para valorar a estudiantes que enfrentan barreras para comunicarse, movilizarse o acceder a la información. Al comenzar el año escolar, Mariana, una estudiante de trece años, llegó trasladada desde otra institución para ingresar a grado séptimo. Su constancia de desempeño indicaba que había sido promovida y que presentaba desempeño alto en Matemáticas y Ciencias Naturales, básico en Lengua Castellana e Inglés y superior en Educación Artística. Mariana tiene una condición motora que afecta principalmente el control de sus movimientos, la postura y la producción oral. Se desplaza en silla de ruedas y utiliza una tableta con un programa de comunicación para expresar ideas extensas. Puede responder oralmente mediante frases cortas, pero requiere más tiempo para organizar sus respuestas. Sus movimientos involuntarios dificultan la escritura manual, especialmente cuando debe copiar textos largos, marcar respuestas en formatos pequeños o desarrollar actividades dentro de tiempos reducidos. La estudiante comprende instrucciones complejas, disfruta resolver problemas matemáticos, participa activamente cuando se le permite utilizar recursos tecnológicos y demuestra especial interés por la astronomía, la robótica y la elaboración de relatos ilustrados. En la institución anterior utilizaba teclado, organizadores gráficos, textos digitales, tiempo adicional, reducción de ejercicios repetitivos y diferentes formas de presentar sus aprendizajes. La madre de Mariana entregó una copia de un informe clínico elaborado tres años atrás, la constancia de promoción y algunos boletines. Explicó que no tenía una certificación reciente porque las citas con especialistas habían sido aplazadas varias veces. También manifestó que el colegio anterior no le entregó todos los documentos pedagógicos, aunque llevaba en una memoria digital algunas guías, trabajos de Mariana y un informe elaborado por su antigua directora de grupo. La secretaria académica informó que la institución no podía garantizar apoyos hasta recibir una certificación actualizada. Sugirió matricular provisionalmente a Mariana en sexto grado, pues consideraba conveniente observar si podía responder a las exigencias académicas antes de ubicarla definitivamente en séptimo. El rector expresó que la institución no debía negar el cupo, pero manifestó preocupación porque no contaba con un profesional permanente para acompañar a Mariana. Propuso matricularla en séptimo, permitirle asistir durante un mes y posteriormente decidir si debía permanecer en ese grado o regresar a sexto. La madre se opuso, argumentando que su hija había sido promovida y que una nueva valoración debería servir para establecer los apoyos requeridos, no para desconocer su trayectoria escolar. La docente de apoyo pedagógico, que visitaba la institución dos veces por semana, explicó que la ausencia de una certificación reciente no impedía identificar barreras ni iniciar acciones para garantizar la participación. Sugirió revisar la información disponible, conversar con Mariana y su familia, observarla en diferentes actividades y realizar una valoración pedagógica que permitiera reconocer sus fortalezas, intereses, formas de comunicación, necesidades de apoyo y condiciones del entorno escolar. Durante las primeras semanas, Mariana encontró varias dificultades. El salón de séptimo estaba ubicado en el segundo piso y el edificio no tenía ascensor. La coordinación decidió trasladar el grupo a un aula del primer piso, pero algunos docentes se mostraron inconformes porque debían desplazarse con sus materiales. El laboratorio de ciencias permanecía en el segundo piso y la biblioteca tenía un escalón en la entrada. El rector solicitó a la secretaría de educación apoyo para realizar adecuaciones, pero mientras se recibía una respuesta indicó que los docentes debían encontrar alternativas que evitaran excluir a Mariana de las actividades institucionales. En la primera reunión del equipo docente, la profesora de Lengua Castellana sostuvo que Mariana debía trabajar con contenidos “más sencillos” para evitar frustraciones. Preparó para ella ejercicios de completar palabras, colorear personajes y copiar oraciones cortas, mientras el resto del grupo analizaba la intención comunicativa de diferentes textos narrativos. La docente consideraba que esas actividades eran apropiadas porque Mariana tardaba demasiado en escribir y porque su expresión oral no siempre era comprendida. También propuso que, independientemente de sus resultados, su calificación máxima fuera 3,5, debido a que realizaba actividades diferentes a las del grupo. El profesor de Matemáticas adoptó otra estrategia. Mantuvo los propósitos de aprendizaje relacionados con proporcionalidad, interpretación de gráficos y resolución de problemas, pero permitió que Mariana utilizara una hoja de cálculo, seleccionara datos mediante la tableta y explicara sus procedimientos con apoyos visuales. En las pruebas le asignó tiempo adicional, redujo la cantidad de ejercicios repetitivos y valoró con los mismos criterios la comprensión del problema, la selección de operaciones y la justificación de la respuesta. En el primer examen, Mariana resolvió correctamente cuatro de cinco problemas y explicó mediante una presentación digital cómo había organizado los datos. Algunos docentes cuestionaron que obtuviera una valoración alta porque no había escrito manualmente el procedimiento completo. El profesor respondió que la escritura manual no era la competencia central que estaba evaluando. En Ciencias Naturales, el docente programó una práctica sobre mezclas y separación de sustancias. Debido a que el laboratorio estaba en el segundo piso, inicialmente propuso entregar a Mariana una guía teórica mientras sus compañeros realizaban el experimento. La estudiante manifestó que quería participar y sugirió que la práctica se organizara temporalmente en el aula del primer piso. El profesor consideró que trasladar los materiales implicaba riesgos y trabajo adicional. Como alternativa, ofreció mostrarle un video del experimento. La docente de apoyo señaló que observar un video podía complementar la actividad, pero no reemplazaba necesariamente las oportunidades de manipular materiales, formular hipótesis, registrar resultados y trabajar con sus compañeros. En Educación Física, el profesor propuso eximir a Mariana de las actividades prácticas y calificarla mediante trabajos escritos sobre reglas deportivas. La estudiante explicó que podía realizar ejercicios de coordinación, lanzamientos, desplazamientos y actividades rítmicas con ajustes en el espacio, los implementos y los tiempos. El docente reconoció que nunca había trabajado con una estudiante usuaria de silla de ruedas y expresó temor de ocasionarle una lesión. La madre ofreció compartir recomendaciones generales de los profesionales que conocían a Mariana, pero pidió que no se asumiera que su hija debía permanecer como observadora. En Inglés, la profesora utilizaba pruebas de vocabulario que exigían copiar cuarenta palabras y completar veinte oraciones en treinta minutos. Mariana conocía buena parte del vocabulario, pero solo alcanzaba a responder una tercera parte del examen. La docente le concedió diez minutos adicionales, aunque mantuvo el mismo formato. Al finalizar, registró desempeño bajo porque la estudiante dejó muchas respuestas sin completar. Cuando la madre preguntó por qué no se había permitido responder mediante el teclado, la profesora afirmó que debía aplicar el mismo examen a todos para garantizar igualdad. Añadió que ofrecer una prueba diferente podía interpretarse como una ventaja injustificada. La plataforma digital utilizada para tareas tampoco era completamente accesible. Algunos botones eran demasiado pequeños, las actividades se cerraban automáticamente después de veinte minutos y varios documentos estaban escaneados como imágenes que no podían ser ampliadas con facilidad. Mariana dependía con frecuencia de su madre para ingresar, descargar archivos o enviar tareas. La coordinación sugirió que la familia imprimiera todos los materiales y entregara las respuestas físicamente. La madre manifestó que esa solución trasladaba la responsabilidad a la familia, aumentaba los costos y no resolvía las barreras que también podían afectar a otros estudiantes. Al finalizar el primer periodo, Mariana obtuvo desempeño alto en Matemáticas y Educación Artística, básico en Ciencias Naturales y Tecnología, y bajo en Lengua Castellana, Inglés y Educación Física. En el informe apareció una observación general que decía: “La estudiante presenta dificultades propias de su condición y necesita mayor esfuerzo para alcanzar el nivel del grupo”. La madre consideró que el informe atribuía los resultados exclusivamente a Mariana y no mencionaba las barreras pedagógicas, comunicativas, tecnológicas y físicas que había enfrentado. Solicitó conocer los criterios utilizados, los instrumentos aplicados, las estrategias de apoyo desarrolladas y los procedimientos para presentar una reclamación. Durante una reunión, el coordinador sostuvo que las calificaciones debían mantenerse porque cada docente tenía autonomía para evaluar. La docente de apoyo aclaró que la autonomía pedagógica no significaba desconocer los criterios institucionales, los derechos de la estudiante ni la necesidad de garantizar que los instrumentos realmente permitieran valorar los aprendizajes. El rector convocó a los docentes, a Mariana y a su madre para elaborar un Plan Individual de Ajustes Razonables. En la reunión se revisaron las fortalezas de la estudiante, las barreras identificadas, las metas de aprendizaje, los recursos disponibles, las responsabilidades de cada docente, los ajustes requeridos y los mecanismos de seguimiento. Algunos profesores consideraron que la docente de apoyo debía diseñar todas las actividades, preparar las evaluaciones diferenciadas y asignar las calificaciones. Ella explicó que su función consistía en acompañar, orientar y contribuir a la construcción de estrategias, pero que la planeación, la enseñanza y la evaluación seguían siendo responsabilidades de los docentes de cada área. Mariana pidió que el plan no se limitara a registrar lo que no podía hacer. Solicitó que se incluyeran su interés por la tecnología, su capacidad para resolver problemas, su preferencia por los apoyos visuales y su deseo de participar en la feria científica institucional. El equipo acordó incorporar alternativas para acceder a la información, expresar los aprendizajes y participar en las actividades. También se establecieron ajustes específicos: uso de tableta, teclado y programas de comunicación; tiempo adicional cuando fuera necesario; formatos con letra ampliada; reducción de copia repetitiva; posibilidad de responder mediante audios, presentaciones, selección de opciones o producción digital; adaptación del mobiliario; ubicación accesible de las actividades y acompañamiento en las transiciones entre espacios. No obstante, algunos docentes interpretaron el plan como autorización para disminuir permanentemente los contenidos. En Lengua Castellana, la profesora continuó entregando actividades correspondientes a grados inferiores y dejó de incluir a Mariana en los debates, pues consideraba que su participación retrasaba la clase. En el segundo periodo, la docente de apoyo observó que Mariana comprendía los textos narrativos trabajados por el curso cuando podía escucharlos, leerlos en formato digital y organizar sus respuestas mediante mapas conceptuales. En una actividad accesible, identificó el conflicto de un cuento, explicó las motivaciones de los personajes y comparó dos desenlaces posibles. Estos resultados contrastaban con las bajas calificaciones obtenidas en ejercicios de copia. El equipo docente también descubrió que las actividades de recuperación solo se ofrecían al finalizar el periodo, cuando ya se habían acumulado varias dificultades. La madre solicitó que los apoyos fueran continuos y que la evaluación sirviera para reorientar oportunamente la enseñanza, no únicamente para registrar resultados finales. Durante el tercer periodo, Mariana faltó diecisiete días debido a una cirugía y a sesiones de rehabilitación. La familia entregó los soportes correspondientes y mantuvo comunicación con la institución. Algunos docentes enviaron actividades por correo, pero otros registraron ausencias sin ofrecer alternativas para acceder a los aprendizajes. Al calcular el porcentaje anual, la coordinación encontró que Mariana había superado el límite de inasistencia establecido institucionalmente. Un grupo de docentes sostuvo que debía reprobar automáticamente, pues modificar el criterio podría ser injusto con los demás estudiantes. Otros señalaron que era necesario analizar las causas de las ausencias, las oportunidades reales de aprendizaje, las evidencias obtenidas, los apoyos ofrecidos y las condiciones particulares de su trayectoria educativa. Al acercarse el final del año, Mariana había alcanzado desempeño alto en Matemáticas, Tecnología y Educación Artística; básico en Ciencias Naturales, Ciencias Sociales e Inglés; y continuaba con desempeño bajo en Lengua Castellana. En Educación Física había mejorado después de que el docente incorporó actividades adaptadas de precisión, coordinación y trabajo cooperativo. La profesora de Lengua Castellana argumentó que Mariana no debía ser promovida porque no había completado todas las pruebas escritas ni producido textos manuscritos de la misma extensión que sus compañeros. La docente de apoyo presentó evidencias de producciones digitales, análisis orales, mapas conceptuales y relatos construidos mediante la tableta. Explicó que era necesario diferenciar la competencia comunicativa que se pretendía valorar de la dificultad motora para escribir manualmente. La madre, preocupada por una posible reprobación, solicitó que Mariana fuera promovida automáticamente por su condición. El rector manifestó que la institución no podía convertir la discapacidad en razón automática para promoverla ni para reprobarla. La decisión debía sustentarse en evidencias pertinentes, en las competencias desarrolladas, en los ajustes implementados, en su trayectoria, en el riesgo de deserción, en su proyecto de vida y en los criterios institucionales revisados desde un enfoque inclusivo. El consejo académico encontró además que varios ajustes acordados no se habían aplicado de forma consistente. La plataforma seguía siendo inaccesible, algunas evaluaciones continuaban dependiendo de la velocidad de escritura y el laboratorio aún no podía ser utilizado por Mariana. También se comprobó que las actividades de apoyo habían sido ocasionales y que no todos los docentes habían registrado los avances, dificultades y compromisos. Ante esta situación, el rector propuso revisar las calificaciones obtenidas mediante instrumentos que no permitieron a Mariana demostrar lo aprendido. Algunos docentes se opusieron porque consideraban que cambiar una valoración después de terminar el periodo afectaría la autoridad del profesor. Otros argumentaron que mantener una calificación derivada de una barrera no corregida tampoco garantizaba objetividad. El equipo directivo reconoció que el caso no podía resolverse únicamente modificando las notas de Mariana. Era necesario revisar el sistema institucional de evaluación, los criterios de promoción, los instrumentos, las estrategias de apoyo, la accesibilidad de los informes y los mecanismos de reclamación. Se propuso conformar mesas de trabajo con docentes, estudiantes, familias, representantes del gobierno escolar y profesionales de apoyo. Las modificaciones serían analizadas por las instancias académicas, aprobadas institucionalmente, incorporadas al proyecto educativo y divulgadas a toda la comunidad. Al finalizar el año, los docentes elaboraron el informe periódico de Mariana y discutieron si debía recibir un documento completamente diferente al de sus compañeros. La docente de apoyo explicó que debía recibir los mismos informes institucionales, pero que, cuando existieran ajustes particulares en la evaluación, era necesario anexar un informe que describiera las competencias desarrolladas, los avances, los apoyos efectivos, las barreras persistentes y las recomendaciones para el grado siguiente. La madre informó que posiblemente la familia tendría que trasladarse a otro municipio. Solicitó copia de la historia escolar, los planes individuales, los seguimientos, los informes de competencias y los acuerdos construidos. El rector indicó que esa documentación debía manejarse de manera confidencial y entregarse al nuevo establecimiento para favorecer la continuidad del proceso. Finalmente, la institución decidió desarrollar un plan de mejoramiento que incluyera formación docente, adecuaciones progresivas de infraestructura, revisión de la plataforma, diversificación de las evaluaciones, seguimiento a los ajustes, participación de las familias, actualización de las historias escolares y análisis periódico de los resultados para identificar prácticas que estuvieran afectando el aprendizaje y la permanencia de los estudiantes.'),
    ('elkin-situacion-3', '51-75', 'pedagogica', 'Competencias comportamentales docentes', 'C. aplique los mismos promedios y porcentajes establecidos para todos, considerando que los ajustes modifican la forma de responder, pero no pueden influir en la promoción. Pregunta 25 El plan institucional que responde de manera más completa a las dificultades identificadas es aquel que: A. articula accesibilidad, planeación para la diversidad, ajustes individuales, evaluación formativa, revisión del sistema institucional, formación docente, participación familiar y seguimiento a resultados. B. concentra los esfuerzos en perfeccionar el plan individual de Mariana, adquirir tecnología especializada y asignar a la docente de apoyo la coordinación de todas las evaluaciones. C. crea criterios de evaluación y promoción diferenciados para estudiantes con discapacidad, reduce los contenidos obligatorios y establece actividades separadas que faciliten su permanencia. Situación 3. Un proyecto común entre diferencias, tensiones y responsabilidades compartidas La Institución Educativa Integrada El Cedral ofrece educación preescolar, básica primaria, básica secundaria y media en un municipio colombiano cuya población combina actividades agrícolas, pequeños comercios, transporte informal y empleos temporales en municipios cercanos. La institución tiene una sede principal y dos sedes rurales. En la sede principal funcionan transición, primaria y bachillerato, aunque cada nivel ocupa un bloque diferente y desarrolla la mayoría de sus actividades de manera independiente. En la autoevaluación institucional del año anterior se identificaron varias dificultades: poca articulación entre los niveles educativos, escasa participación de las familias, baja comunicación entre docentes, conflictos frecuentes durante los descansos compartidos y una percepción generalizada de que cada sección trabajaba exclusivamente por sus propios resultados. Las maestras de preescolar afirmaban que sus propuestas eran consideradas actividades recreativas sin suficiente valor pedagógico. Los docentes de primaria manifestaban que debían asumir la transición de estudiantes que llegaban a primero sin rutinas comunes de trabajo. Algunos profesores de bachillerato sostenían que no podían destinar tiempo a proyectos institucionales porque debían concentrarse en preparar a sus estudiantes para evaluaciones externas y para la educación superior. Las familias también expresaron inconformidades. Varias señalaron que el colegio solo las contactaba cuando existían problemas académicos o disciplinarios. Otras indicaron que recibían mensajes diferentes de cada docente, en horarios poco adecuados y por canales informales. Los estudiantes de secundaria, por su parte, afirmaron que pocas veces eran escuchados en la planeación de actividades institucionales. Ante esta situación, el consejo directivo aprobó la realización del proyecto “Puentes que enseñan: territorio, convivencia y participación”, cuyo propósito era integrar a estudiantes, docentes y familias de todos los niveles en una experiencia pedagógica común. El proyecto debía culminar con una muestra institucional en la que se presentaran relatos del territorio, juegos tradicionales, experiencias científicas, producciones artísticas, proyectos tecnológicos y propuestas juveniles para mejorar la convivencia. El rector conformó un equipo coordinador integrado por Laura Martínez, docente de preescolar; Daniel Rincón, docente de primaria; Marcela Gómez, docente de bachillerato; la orientadora escolar; un representante estudiantil y una representante de las familias. Laura era reconocida por su cercanía con los niños, su creatividad y su habilidad para vincular el juego, el arte, la literatura y la exploración del medio. Sin embargo, algunos compañeros consideraban que tendía a proteger demasiado a sus estudiantes y que, ante actividades institucionales, prefería controlar cada detalle en lugar de permitir que otros participaran. Daniel era un docente organizado, cumplido y orientado a alcanzar resultados concretos. Sus estudiantes solían obtener buenos desempeños y él acostumbraba llevar registros detallados de sus actividades. No obstante, durante las reuniones hablaba extensamente, corregía con frecuencia las propuestas de los demás y asumía tareas sin consultar al equipo porque consideraba que así se garantizaba mayor eficiencia. Marcela enseñaba Ciencias Sociales y Ciencias Políticas en los grados noveno, décimo y undécimo. Tenía buen dominio de su área, argumentaba con claridad y exigía altos niveles de desempeño a sus estudiantes. Aunque participaba activamente en los proyectos académicos de bachillerato, manifestaba dudas frente a las actividades que involucraban a los niveles iniciales, pues creía que podían disminuir el tiempo destinado a los contenidos de su asignatura. En la primera reunión del equipo coordinador, Laura propuso una ruta sensorial en la que los niños de transición presentarían sonidos, semillas, relatos familiares y representaciones artísticas relacionadas con la vida del municipio. Daniel sugirió que los estudiantes de primaria construyeran mapas ilustrados y pequeñas exposiciones sobre los cambios del territorio. Marcela planteó que los jóvenes de bachillerato elaboraran pódcast y debates sobre participación ciudadana. Cuando Laura explicó su propuesta, Marcela comentó que la muestra institucional no debía convertirse en una sucesión de “manualidades infantiles”, pues era necesario presentar productos académicos de mayor profundidad. Laura se sintió descalificada y respondió que algunos docentes de bachillerato confundían la dificultad de los contenidos con la calidad pedagógica. El ambiente se volvió tenso. Daniel intervino señalando que el proyecto debía mostrar una progresión de aprendizajes desde preescolar hasta grado undécimo. Propuso que cada integrante explicara qué podía aportar su nivel al objetivo común y que, antes de discutir actividades específicas, acordaran los resultados institucionales que esperaban alcanzar. El representante estudiantil, Nicolás, sugirió que los jóvenes de décimo y undécimo acompañaran a los niños más pequeños durante la muestra. Consideraba que la experiencia podía fortalecer el liderazgo estudiantil y reducir las burlas que algunos adolescentes dirigían a los estudiantes de primaria. La representante de las familias, Rosa, propuso invitar a artesanos, agricultores y adultos mayores para compartir conocimientos sobre la historia local. El equipo acordó que la muestra no estaría organizada como actividades separadas, sino como un recorrido en el que cada nivel aportaría desde sus capacidades. También definieron tres propósitos comunes: fortalecer el sentido de pertenencia, mejorar las relaciones entre los niveles y aumentar la participación de las familias. Daniel creó un cronograma digital, distribuyó tareas y abrió una carpeta compartida. Aunque el documento facilitó la organización, asignó fechas y responsabilidades sin consultar previamente la disponibilidad de todos. Marcela manifestó que debía acompañar a grado undécimo en actividades de preparación académica durante dos de las fechas seleccionadas. Laura indicó que los horarios establecidos coincidían con momentos sensibles de alimentación y descanso de los niños de transición. Daniel respondió que era difícil organizar un proyecto si cada persona planteaba restricciones particulares. Marcela consideró que el cronograma debía respetarse porque ya había sido enviado. Laura propuso revisarlo, pero Daniel insistió en que modificarlo generaría desorden. Días después, la coordinadora académica pidió al equipo que presentara avances. Daniel habló durante casi toda la reunión, describió las tareas realizadas y respondió las preguntas sin permitir que Laura y Marcela explicaran sus propios procesos. Al finalizar, Marcela le manifestó en privado que su forma de dirigir las reuniones hacía que los demás parecieran simples ejecutores. Daniel se sintió incómodo. Consideraba que su intervención había evitado silencios y demostrado que el equipo estaba trabajando. Sin embargo, revisó la grabación de la reunión y reconoció que había ocupado la mayor parte del tiempo. Decidió proponer una agenda con turnos de participación y responsables diferentes para las siguientes sesiones. Mientras avanzaba la planeación, la institución recibió la noticia de que el presupuesto destinado al proyecto sería menor de lo esperado. No podrían contratar sonido profesional, imprimir todos los materiales ni comprar los elementos decorativos solicitados. Algunos docentes propusieron reducir el proyecto a una exposición sencilla dentro de cada salón. Laura sugirió utilizar materiales reutilizables, solicitar préstamos de equipos a la biblioteca municipal y vincular a familias que poseían conocimientos de carpintería, costura y producción audiovisual. Marcela propuso que los estudiantes de tecnología revisaran los equipos disponibles y diseñaran soluciones de bajo costo. El equipo decidió mantener el proyecto, pero reformularlo. La medida exigía que los docentes compartieran recursos y renunciaran a algunos elementos que habían considerado indispensables. En preescolar, Laura comenzó a preparar a sus estudiantes para interactuar con jóvenes de bachillerato. Uno de los niños, Mateo, se mostraba ansioso frente a espacios con mucho ruido y gran cantidad de personas. Su familia explicó que podía participar si conocía previamente el recorrido, contaba con un lugar tranquilo y tenía un adulto de referencia. Laura consideró inicialmente que lo mejor era que Mateo asistiera solo durante una parte de la muestra para evitarle malestar. La orientadora le propuso preparar anticipadamente al niño, organizar apoyos visuales, establecer pausas y permitirle participar en las actividades que pudiera disfrutar. Laura reconoció que su intención de protegerlo podía terminar limitando su participación y aceptó ajustar la propuesta. En primaria, los estudiantes debían trabajar en equipos para elaborar mapas sobre lugares importantes del municipio. Daniel encontró que algunos grupos distribuían las tareas de manera desigual. Los estudiantes con mejor desempeño realizaban los textos y dibujos, mientras otros se encargaban exclusivamente de llevar materiales. Para asegurar que todos aprendieran, Daniel propuso roles rotativos y momentos de autoevaluación. Sin embargo, ante la cercanía de la fecha, estuvo tentado a seleccionar únicamente los mejores trabajos. Una colega le recordó que el proyecto no buscaba exhibir solo productos perfectos, sino mostrar procesos de aprendizaje y participación. En bachillerato, Marcela invitó a sus estudiantes a elaborar pódcast sobre transformaciones sociales del municipio. Algunos jóvenes propusieron entrevistar a vendedores informales, líderes comunitarios, campesinos y funcionarios locales. Marcela consideró que la idea enriquecía el proyecto, aunque implicaba reorganizar su planeación. También propuso que los estudiantes mayores acompañaran a los niños de preescolar y primaria durante el evento. Para ello estableció responsabilidades, realizó ensayos y conversó con ellos sobre el trato respetuoso, el cuidado y el lenguaje que debían utilizar. Les expresó que confiaba en su capacidad para asumir un papel positivo frente a los estudiantes más pequeños. Durante la preparación surgió un conflicto en el grupo de mensajería de los docentes. Laura envió una imagen con la distribución de los espacios y escribió: “Ojalá esta vez sí respetemos lo acordado”. Marcela interpretó el mensaje como una acusación directa y respondió que bachillerato no podía adaptarse permanentemente a las necesidades de preescolar. Otros docentes comenzaron a opinar. Algunos respaldaron a Laura y otros a Marcela. Daniel escribió un mensaje extenso en el que explicó quién tenía razón según los acuerdos anteriores. La conversación aumentó de tono. La orientadora propuso detener la discusión y llevar el asunto a una reunión breve. En ese espacio, Laura reconoció que su mensaje podía interpretarse como una recriminación. Marcela explicó que se sentía presionada porque debía cumplir simultáneamente con varias responsabilidades. Ambas identificaron que el problema no era únicamente la distribución de los espacios, sino la percepción de que los niveles competían por los recursos institucionales. El equipo revisó las necesidades de cada grupo y estableció criterios compartidos para asignar aulas, patios y equipos. También acordaron registrar las decisiones y verificar su cumplimiento en una reunión posterior. Una semana después, la madre de una estudiante de primaria publicó en una red social que el proyecto favorecía a ciertos cursos y que algunos docentes “escogían siempre a los mismos niños”. La publicación comenzó a ser compartida por otras familias. Daniel quiso responder inmediatamente para defender a la institución y explicar que la acusación era injusta. El rector le pidió no iniciar una discusión pública. Se comunicaron con la madre, escucharon sus preocupaciones y descubrieron que su hija había participado poco en la elaboración del mapa porque sus compañeros no le permitían escribir. El equipo se comprometió a revisar la distribución de roles y a informar a las familias sobre los criterios de participación. La madre aceptó retirar algunas afirmaciones ofensivas, pero pidió que el colegio no se limitara a proteger su imagen. En bachillerato ocurrió otra situación. Un estudiante grabó a varios niños de preescolar mientras ensayaban una ronda y publicó el video con comentarios burlones. Otros jóvenes reaccionaron con emoticones de risa. Marcela informó la situación, solicitó que se retirara el contenido y conversó con los estudiantes implicados. Algunos docentes propusieron suspender inmediatamente al autor del video. Otros consideraron suficiente pedirle una disculpa. El equipo decidió proteger a los niños, informar a las familias cuando correspondiera, trabajar con los estudiantes responsables y analizar la participación de quienes reforzaron la publicación. Además de las medidas establecidas institucionalmente, organizaron una actividad sobre dignidad, cuidado, responsabilidad digital y reparación del daño. Durante esa misma semana, Laura enfermó y recibió una incapacidad médica. Sus compañeros debían continuar los ensayos de preescolar. Inicialmente, varios manifestaron que no conocían la propuesta y que no podían asumir responsabilidades adicionales. Daniel revisó los materiales compartidos, habló con la docente que acompañaba el grupo y redistribuyó temporalmente algunas tareas. Marcela consiguió que dos estudiantes de undécimo apoyaran la preparación de los elementos tecnológicos, bajo supervisión docente. El equipo evitó cancelar la participación de preescolar, pero también acordó que la redistribución sería temporal y que no debía convertirse en una sobrecarga permanente para determinados docentes. A pocos días del evento, la coordinación pidió autorización para publicar fotografías y videos promocionales. Un docente sugirió utilizar todas las imágenes porque el proyecto era institucional y las familias ya conocían que se realizaría la muestra. Laura recordó que algunas familias no habían autorizado la publicación de imágenes. Marcela propuso revisar los consentimientos, seleccionar únicamente contenidos permitidos y evitar información que expusiera innecesariamente a los estudiantes. El día anterior a la muestra, el servicio meteorológico anunció fuertes lluvias. Parte del evento estaba planeado para espacios abiertos. El rector consideró aplazarlo, pero muchas familias y participantes externos ya habían organizado su asistencia. El equipo activó un plan alternativo: reorganizó aulas, modificó el recorrido, protegió los equipos, informó a las familias y asignó nuevas responsabilidades. La decisión exigió renunciar a algunas actividades, pero permitió mantener los propósitos centrales sin comprometer la seguridad. Durante el evento se presentaron dificultades. El sistema de sonido falló por algunos minutos, dos familias invitadas llegaron tarde y varios estudiantes de bachillerato abandonaron temporalmente sus puestos de acompañamiento. Sin embargo, los niños, jóvenes y familias participaron activamente en la mayoría de las estaciones. La ruta sensorial de preescolar permitió que los visitantes reconocieran plantas, sonidos y relatos del territorio. Los mapas de primaria mostraron problemas ambientales y lugares significativos. Los pódcast de bachillerato generaron conversaciones sobre participación juvenil, empleo y transformaciones comunitarias. Al finalizar, algunos docentes celebraron el éxito de la actividad y propusieron cerrar el proyecto con una publicación institucional. El rector solicitó primero una evaluación. Los registros mostraron que la participación de las familias había aumentado, pero seguía siendo baja en las veredas más alejadas. También se encontró que algunos estudiantes asumieron casi todas las funciones visibles, mientras otros tuvieron una participación limitada. Los jóvenes que acompañaron a los niños valoraron positivamente la experiencia, aunque varios reconocieron que no recibieron suficiente orientación para resolver situaciones imprevistas. Marcela admitió que al comienzo había subestimado los aportes de preescolar y primaria. Laura reconoció que, en algunos momentos, había querido controlar excesivamente las actividades de sus estudiantes. Daniel aceptó que su preocupación por cumplir las metas lo llevaba a centralizar decisiones. El equipo propuso mantener el proyecto durante el siguiente año, pero con reuniones más participativas, responsabilidades rotativas, formación previa de los estudiantes mentores, estrategias para vincular a las familias rurales y mecanismos de seguimiento. La coordinadora académica pidió que el informe final destacara únicamente los resultados positivos, pues sería enviado a posibles aliados. Marcela señaló que ocultar las dificultades impediría aprender de ellas. Laura propuso presentar los logros, las limitaciones y un plan concreto de mejoramiento. Semanas después, un docente que no había participado activamente afirmó ante el rector que el proyecto había funcionado gracias a su colaboración. Daniel se molestó porque consideraba que otras personas estaban atribuyéndose el trabajo del equipo. Pensó en confrontarlo durante la reunión general, pero decidió hablar primero con él en privado, aclarar las responsabilidades y solicitar que el informe reconociera de manera objetiva los aportes de todos. El rector concluyó que el mayor resultado del proyecto no era únicamente la muestra realizada, sino la posibilidad de transformar la forma en que los docentes se comunicaban, asumían responsabilidades, resolvían desacuerdos y trabajaban por objetivos institucionales comunes.'),
    ('elkin-situacion-4', '76-100', 'razonamiento', 'Razonamiento cuantitativo y lectura critica', 'Pregunta 25 Ante el conjunto de dificultades presentadas, la actuación profesional más completa del equipo docente sería: A. establecer una coordinación central fuerte que distribuya funciones, controle los resultados y reduzca la posibilidad de desacuerdos. B. construir una visión común, comunicarse con respeto, colaborar, mediar los conflictos, actuar con iniciativa, cumplir los compromisos y evaluar continuamente los resultados. C. permitir que cada nivel conserve autonomía plena, reuniéndose únicamente cuando existan problemas que afecten a toda la institución. Situación 4. Datos que orientan, textos que deben interpretarse y decisiones que exigen planeación La Institución Educativa Departamental Río de Colores está ubicada en un municipio colombiano con población urbana y rural. Atiende aproximadamente a mil estudiantes desde preescolar hasta grado undécimo y cuenta con tres sedes: una sede central donde funcionan secundaria y media, y dos sedes de primaria ubicadas en sectores con condiciones sociales y económicas diferentes. Durante la autoevaluación institucional del año anterior, los docentes identificaron que muchos estudiantes podían localizar información explícita en un texto, pero tenían dificultades para establecer relaciones entre ideas, reconocer la intención del autor, comparar argumentos, interpretar datos presentados en situaciones escolares y justificar conclusiones con evidencias. Los resultados internos también mostraron que algunos estudiantes resolvían operaciones básicas cuando estas se presentaban de manera directa, pero se confundían cuando debían decidir qué información era relevante, comparar cantidades pertenecientes a grupos de diferente tamaño, interpretar cambios entre dos momentos o determinar si una afirmación estaba realmente respaldada por los datos. Ante esta situación, el consejo académico aprobó el proyecto institucional “Leer, analizar y decidir”, que tendría una duración inicial de seis semanas. El proyecto debía integrar actividades de lectura crítica, interpretación de información cuantitativa y planeación pedagógica en los grados quinto, séptimo y noveno. La coordinadora académica, Sandra Beltrán, explicó que el propósito no era aumentar el número de talleres, sino mejorar la manera en que los estudiantes comprendían problemas, examinaban evidencias y comunicaban sus decisiones. También indicó que los resultados debían utilizarse para ajustar la enseñanza, no únicamente para clasificar a los estudiantes. Antes de diseñar las actividades, se aplicó una prueba diagnóstica con dos componentes. El primero evaluaba la comprensión de información implícita, la relación entre partes de un texto y la justificación de conclusiones. El segundo presentaba situaciones con cantidades, porcentajes y comparaciones, pero exigía principalmente interpretar los datos y argumentar decisiones. En quinto A había treinta estudiantes. Doce quedaron en desempeño bajo en lectura inferencial y nueve en interpretación cuantitativa. En quinto B había veinte estudiantes. Nueve quedaron en desempeño bajo en lectura inferencial y cinco en interpretación cuantitativa. En séptimo A había treinta y seis estudiantes. Quince presentaron desempeño bajo en lectura inferencial y catorce en interpretación cuantitativa. En séptimo B había veinticuatro estudiantes. Once quedaron en desempeño bajo en lectura inferencial y ocho en interpretación cuantitativa. En noveno A había treinta y dos estudiantes. Ocho obtuvieron desempeño bajo en lectura inferencial y trece en interpretación cuantitativa. En noveno B había veintiocho estudiantes. Ocho quedaron en desempeño bajo en lectura inferencial y diez en interpretación cuantitativa. Durante la primera reunión, el profesor Julián, docente de Matemáticas, afirmó que séptimo A debía recibir la mayor cantidad de apoyos de lectura porque tenía quince estudiantes en desempeño bajo, la cifra más alta de todos los grupos. La profesora Diana, de Lengua Castellana, señaló que la comparación debía considerar también el tamaño de cada curso, pues once estudiantes representaban una parte más grande de séptimo B que quince estudiantes de séptimo A. El rector observó que noveno A y noveno B tenían solamente ocho estudiantes con desempeño bajo en lectura. A partir de ese dato, sugirió concentrar el proyecto en quinto y séptimo, debido a que la situación de noveno parecía menos preocupante. La coordinadora pidió no tomar decisiones basadas en una sola cifra. Recordó que en noveno A existía una dificultad importante en interpretación cuantitativa, pues trece de los treinta y dos estudiantes no lograban analizar adecuadamente información numérica dentro de un contexto. Además, señaló que los ocho estudiantes con dificultad lectora representaban una proporción diferente en cada grupo de noveno. El equipo docente debía seleccionar los grupos que participarían en el primer ciclo intensivo de lectura. Solo podían atender inicialmente a dos grupos, porque durante las primeras dos semanas había disponibilidad limitada de docentes y espacios. Algunos profesores propusieron comenzar con los grupos que tenían el mayor número absoluto de estudiantes en desempeño bajo. Otros plantearon iniciar con los cursos donde la proporción de estudiantes con dificultades era más alta, sin excluir posteriormente a los demás grupos. Al revisar los resultados de quinto, el equipo encontró que quinto A tenía más estudiantes con desempeño bajo en lectura que quinto B. Sin embargo, en quinto A doce de treinta estudiantes se encontraban en esa condición, mientras que en quinto B eran nueve de veinte. Una situación similar aparecía en séptimo. Aunque séptimo A tenía quince estudiantes con desempeño bajo y séptimo B once, la cantidad total de estudiantes era diferente. La discusión permitió reconocer que comparar únicamente números absolutos podía conducir a decisiones poco equitativas. En el documento inicial del proyecto, uno de los objetivos aparecía formulado de la siguiente manera: “Mejorar la lectura y las matemáticas de todos los estudiantes mediante actividades interesantes”. La coordinadora consideró que el objetivo era demasiado general. No indicaba qué aprendizajes se pretendían fortalecer, con qué estudiantes se trabajaría primero, qué cambios se esperaban ni qué evidencias permitirían verificar los resultados. Después de analizarlo, el equipo propuso una formulación más precisa: fortalecer la capacidad de identificar relaciones implícitas, justificar conclusiones con evidencias e interpretar información cuantitativa en situaciones escolares, estableciendo metas diferenciadas para los grupos según los resultados diagnósticos. Para organizar el proyecto, algunos docentes querían comenzar inmediatamente con las actividades. Sandra insistió en que primero debían revisar la información disponible, definir los aprendizajes prioritarios, establecer las metas, seleccionar las estrategias, distribuir responsabilidades, organizar los recursos y acordar cómo se realizaría el seguimiento. El plan estableció dos sesiones semanales de cuarenta y cinco minutos. Una sesión estaría orientada al análisis de textos y argumentos; la otra integraría situaciones cuantitativas relacionadas con asistencia, convivencia, uso de recursos, resultados académicos y participación estudiantil. Los docentes acordaron que las actividades no debían reducirse a operaciones aisladas. Por ejemplo, un estudiante podía calcular correctamente una cantidad y aun así interpretar mal lo que esa cantidad significaba dentro del problema. Por ello, las respuestas debían incluir una explicación de la decisión adoptada. Para el primer taller, Diana seleccionó una noticia escolar sobre una campaña de reciclaje. El texto afirmaba: “La campaña fue un éxito absoluto porque el grupo que recogió más kilogramos de material fue también el grupo más comprometido con el cuidado ambiental”. La noticia informaba que sexto A, con treinta y ocho estudiantes, había recogido ciento catorce kilogramos, mientras que sexto B, con veinticuatro estudiantes, había recogido noventa y seis. No se mencionaba cuántos estudiantes habían participado realmente, qué tipo de material se había recogido ni qué otras acciones ambientales había desarrollado cada curso. Diana quería que los estudiantes identificaran que la conclusión de la noticia era más amplia que las evidencias presentadas. Recoger una cantidad mayor no demostraba por sí mismo que un grupo tuviera mayor compromiso ambiental, especialmente cuando los grupos tenían tamaños diferentes y no se habían considerado otras conductas. En Matemáticas, Julián preparó una actividad sobre el uso de la biblioteca. El informe indicaba que durante un mes quinto A había realizado noventa préstamos y quinto B setenta. Su primera pregunta era: “¿Qué grupo lee más?”. Sandra sugirió modificarla porque la cantidad de préstamos no permitía afirmar directamente cuánto había leído cada estudiante. El equipo propuso que los estudiantes compararan la cantidad de préstamos con el número de integrantes de cada grupo, identificaran información faltante y explicaran qué conclusiones podían sostenerse y cuáles requerían nuevas evidencias. Para realizar las actividades digitales, la institución disponía de dieciocho tabletas. Los grupos seleccionados tenían entre veinte y treinta y dos estudiantes. Un docente propuso entregar todos los dispositivos a los estudiantes con mejor desempeño, para que ellos orientaran a sus compañeros. Otro sugirió reservarlos exclusivamente para quienes presentaban dificultades. La coordinadora recomendó organizar estaciones de trabajo. En una estación se utilizarían las tabletas en parejas o grupos pequeños; en otra se analizarían textos impresos; y en una tercera se desarrollarían discusiones orientadas por el docente. De esta manera, todos los estudiantes podrían utilizar los recursos durante una parte de la sesión y trabajar las mismas competencias mediante diferentes actividades. En la planeación de una clase de Lengua Castellana, la docente escribió como propósito: “Inferir la intención del autor y evaluar la solidez de sus argumentos”. Sin embargo, la actividad principal consistía en copiar las definiciones de tesis, argumento y conclusión. La evaluación final pedía unir cada concepto con su definición. La coordinadora señaló que existía una falta de correspondencia entre el propósito, la actividad y la evaluación. Los estudiantes podían memorizar las definiciones sin demostrar que sabían reconocer la intención de un autor o valorar la calidad de un argumento. Para mejorar la planeación, propusieron presentar dos textos con posiciones diferentes sobre el uso de teléfonos celulares en la escuela. Los estudiantes tendrían que identificar la intención de cada autor, comparar las evidencias utilizadas y justificar cuál argumento consideraban mejor sustentado. En las primeras dos semanas participaron sesenta estudiantes en las sesiones intensivas. Al finalizar el primer ciclo, cuarenta y ocho mejoraron por lo menos uno de los criterios evaluados. Doce permanecieron en el mismo nivel. En el informe preliminar, un docente escribió: “La mayoría de los estudiantes mejoró, por tanto, el proyecto demostró ser la causa directa del avance académico”. Sandra estuvo de acuerdo en que los resultados eran alentadores, pero consideró que la afirmación debía redactarse con mayor cuidado. No se había analizado aún qué otros factores podían haber influido, ni se había comparado completamente el proceso con estudiantes que no asistieron regularmente a las sesiones. Durante el mismo periodo, cuarenta estudiantes con dificultades similares no participaron de manera constante en el proyecto. Veintidós de ellos también mejoraron al menos uno de los criterios. Los docentes descubrieron que quienes asistieron con mayor frecuencia al proyecto también tenían, en promedio, mejor asistencia general a clases y mayor acompañamiento familiar. Estos datos no invalidaban el proyecto, pero dificultaban afirmar que la intervención era la única causa de la mejora. La participación no había sido completamente aleatoria, y las condiciones de los estudiantes no eran exactamente iguales. Además de las pruebas, se aplicó una encuesta de percepción a cuarenta y ocho estudiantes. Treinta afirmaron que preferían aprender mediante videos; doce eligieron la lectura y discusión en grupo; y seis indicaron que preferían trabajar con guías individuales. Al conocer los resultados, un docente afirmó: “La encuesta demuestra que todos los estudiantes aprenden mejor con videos; por eso deberíamos reemplazar las lecturas impresas”. La coordinadora explicó que la encuesta mostraba una preferencia mayoritaria, no una prueba de que todos aprendieran mejor de la misma forma. También señaló que preferir una actividad no significaba necesariamente que esa actividad fuera la más efectiva para desarrollar una competencia. En otra reunión, un estudiante comentó: “En la evaluación final obtuve una nota más alta porque el texto era más corto, tenía palabras más conocidas y las preguntas me parecieron más directas”. Un profesor utilizó este testimonio para afirmar que el estudiante había desarrollado una comprensión mucho más profunda. Diana advirtió que la declaración también podía indicar que la evaluación final había sido percibida como menos compleja. Por tanto, el testimonio no era suficiente para demostrar por sí solo un avance en lectura crítica. Al finalizar el primer ciclo, los resultados de lectura inferencial mostraron cambios diferentes. En quinto B, el número de estudiantes con desempeño bajo disminuyó de nueve a seis. En séptimo B pasó de once a ocho. En noveno A pasó de ocho a siete. Un docente afirmó que quinto B y séptimo B habían mejorado exactamente en la misma proporción porque en ambos grupos tres estudiantes dejaron de estar en desempeño bajo. La coordinadora respondió que una reducción de tres estudiantes no representaba necesariamente el mismo cambio cuando los puntos de partida eran diferentes. También se observó que la asistencia a las sesiones no había sido igual. En quinto B, la mayoría de los estudiantes participó en por lo menos cinco de las seis actividades programadas. En séptimo B, varios estudiantes faltaron debido a dificultades con las rutas de transporte y responsabilidades familiares. En noveno A, la asistencia fue estable, pero algunos estudiantes manifestaron que las actividades les parecían poco relacionadas con sus intereses. El equipo concluyó que los mismos resultados numéricos podían requerir decisiones pedagógicas diferentes. En quinto B era necesario consolidar los avances. En séptimo B se debía revisar la asistencia y eliminar barreras para la participación. En noveno A convenía ajustar el nivel de complejidad y relacionar las actividades con situaciones propias de los adolescentes. Mientras se analizaban los datos, el rector pidió una noticia breve para las redes sociales institucionales. En un borrador se escribió: “El proyecto redujo a la mitad el número de estudiantes con bajo desempeño: pasamos de veinticuatro a doce”. Sin embargo, al revisar los registros, Diana encontró que la primera cifra correspondía a veinticuatro estudiantes evaluados al comienzo, mientras que la segunda incluía únicamente a dieciocho que presentaron la prueba final. Seis estudiantes ausentes no habían sido clasificados en el segundo momento. El equipo decidió no publicar la afirmación hasta verificar resultados comparables. También acordó que los informes debían aclarar cuántos estudiantes habían sido evaluados, cuántos tenían información completa y qué datos faltaban. En la comunicación con las familias aparecieron otras dificultades. Algunas recibieron tres mensajes distintos durante la misma semana. Un docente informó que las actividades debían entregarse el jueves; otro indicó que el plazo era el viernes; y un tercer mensaje señalaba que la entrega sería durante la siguiente sesión. Una madre escribió: “No estamos rechazando el acompañamiento. Nos preocupa que las tareas lleguen por varios medios, sin una explicación común y con fechas diferentes. Queremos apoyar, pero necesitamos saber qué se espera de nosotros”. Algunos docentes interpretaron el mensaje como una falta de compromiso de las familias. La coordinadora señaló que la madre no estaba rechazando el proyecto, sino solicitando coordinación, claridad y condiciones que permitieran acompañar adecuadamente a los estudiantes. Como respuesta, se propuso enviar una sola comunicación semanal, utilizar un canal institucional definido, señalar los propósitos de las actividades y ofrecer un horario de orientación para las familias que necesitaran aclaraciones. El proceso de seguimiento identificó a setenta y dos estudiantes que requerían una entrevista individual. Cuatro docentes podían realizar seis entrevistas por semana cada uno. Si todos los espacios disponibles se utilizaban y no se presentaban cancelaciones, el equipo podría completar las entrevistas en tres semanas. Algunos profesores propusieron atender primero a quienes tenían las calificaciones más bajas. Otros señalaron que también debían considerarse la inasistencia, los cambios recientes en el desempeño, las dificultades emocionales y el riesgo de desvinculación escolar. En la revisión de los promedios generales, el puntaje institucional de lectura aumentó de 3,1 a 3,5. La coordinadora pidió no interpretar ese resultado de manera aislada. Los estudiantes que inicialmente se encontraban en desempeño alto pasaron, en promedio, de 4,1 a 4,6. Los estudiantes que estaban en desempeño bajo pasaron de 2,4 a 2,6. Aunque el promedio general aumentó, la distancia entre los estudiantes con resultados altos y bajos también se hizo mayor. Esto indicaba que el proyecto había producido avances, pero no necesariamente había reducido las brechas de aprendizaje. En una reunión posterior, el representante estudiantil propuso presentar únicamente el promedio institucional porque era fácil de comprender. Diana recomendó acompañarlo con la cantidad de estudiantes evaluados, los porcentajes por nivel de desempeño, los cambios de cada grupo y la información faltante. El equipo también debía decidir cómo comunicar los resultados sin estigmatizar a los grupos. Se acordó evitar expresiones como “el peor curso” o “los estudiantes que no pueden”. En su lugar, los informes describirían aprendizajes logrados, dificultades persistentes, condiciones que podían estar influyendo y acciones previstas. Cuando faltaban dos semanas para terminar el proyecto, la institución recibió menos recursos de los esperados. No podrían imprimir todas las guías, contratar una plataforma ni ampliar el número de horas docentes. Un grupo propuso suspender la segunda fase. Otro planteó mantener únicamente las actividades que podían realizarse con los recursos existentes, aunque estas no respondieran completamente a los objetivos. Sandra sugirió proteger los componentes esenciales: actividades alineadas con las necesidades diagnósticas, acompañamiento a los grupos prioritarios, seguimiento de resultados y espacios de retroalimentación. Los gastos en decoración, impresiones a color y materiales no indispensables podían reducirse. También podían utilizarse recursos compartidos, textos disponibles en la biblioteca y situaciones construidas por los propios docentes. Para el cierre del proyecto, el rector propuso declarar que la estrategia había sido exitosa porque el promedio general había aumentado y la mayoría de los participantes había mejorado. La coordinadora consideró que el informe final debía incluir los logros, pero también las diferencias entre grupos, las limitaciones de los datos, la asistencia desigual, las barreras identificadas y los ajustes que debían incorporarse al siguiente ciclo. El consejo académico concluyó que la planeación institucional no podía ser un documento fijo. Debía revisarse a partir de evidencias comparables, interpretaciones cuidadosas, opiniones de los estudiantes, participación de las familias y análisis de las condiciones reales de implementación. También reconoció que una cifra podía ser correcta y, aun así, utilizarse de manera engañosa. Un texto podía parecer convincente y, sin embargo, presentar conclusiones que no estaban suficientemente respaldadas. De igual manera, una actividad podía ser atractiva, pero resultar poco pertinente si no guardaba relación con los aprendizajes esperados.')
),
new_questions (
  block_id,
  category_position,
  external_id,
  question_number,
  prompt,
  options,
  correct_answer,
  explanation,
  option_feedback
) as (
  values
    ('elkin-situacion-1', 1, 'elkin-s1-q1', 1, 'Ante el empujón sufrido por Valeria, la actuación inicial más pertinente por parte de la institución es:', '["Separar a los estudiantes, verificar el estado físico y emocional de Valeria, garantizar su seguridad y registrar objetivamente lo ocurrido antes de definir otras medidas.", "Reunir inmediatamente a Valeria y Samuel para contrastar sus versiones, solicitar disculpas mutuas y establecer un compromiso que permita continuar la jornada.", "Solicitar primero los testimonios del curso, determinar quién inició el enfrentamiento y aplicar una medida provisional a quien aparezca como responsable principal."]'::jsonb, 0, 'La prioridad inicial es detener la agresión, proteger a la estudiante, comprobar su estado físico y emocional y dejar un registro objetivo antes de adoptar otras decisiones.', '["La prioridad inicial es detener la agresión, proteger a la estudiante, comprobar su estado físico y emocional y dejar un registro objetivo antes de adoptar otras decisiones.", "Una confrontación inmediata puede aumentar la tensión, exponer nuevamente a Valeria y presentar el caso como un conflicto entre iguales sin analizar los antecedentes.", "Recoger testimonios es necesario, pero no puede anteponerse a la protección inmediata ni depender de establecer primero quién inició la confrontación."]'::jsonb),
    ('elkin-situacion-1', 2, 'elkin-s1-q2', 2, 'Considerando las publicaciones, exclusiones virtuales, burlas reiteradas y afectaciones presentadas por Valeria, la situación debe ser comprendida principalmente como:', '["Un conflicto escolar que aumentó de intensidad porque ambas partes realizaron acciones que afectaron la convivencia del grupo.", "Una forma de agresión repetida y ciberacoso que produjo afectaciones emocionales y se desarrolló en una relación de desequilibrio frente al grupo.", "Una agresión digital aislada que posteriormente se transformó en una confrontación física entre dos estudiantes con responsabilidades equivalentes."]'::jsonb, 1, 'La repetición, la exposición digital, la participación de varios estudiantes y las afectaciones emocionales permiten reconocer una situación de acoso y ciberacoso.', '["No se trata solamente de un desacuerdo entre dos estudiantes, porque las agresiones fueron reiteradas, grupales y desarrolladas en una relación de desequilibrio.", "La repetición, la exposición digital, la participación de varios estudiantes y las afectaciones emocionales permiten reconocer una situación de acoso y ciberacoso.", "Las publicaciones no fueron aisladas y las responsabilidades no son equivalentes, pues Valeria se encontraba en desventaja frente a quienes promovían y reforzaban las agresiones."]'::jsonb),
    ('elkin-situacion-1', 3, 'elkin-s1-q3', 3, 'El elemento que permite diferenciar con mayor precisión lo ocurrido con Valeria de un conflicto ocasional entre compañeros es:', '["La existencia de desacuerdos previos entre los estudiantes y la utilización de medios digitales para comunicar opiniones ofensivas.", "La presencia de una agresión física posterior a varias bromas y la participación de estudiantes que reaccionaron ante las publicaciones.", "La repetición de las conductas, la afectación sostenida y la posición de desventaja de Valeria frente a quienes promovieron o reforzaron las agresiones."]'::jsonb, 2, 'La reiteración, la continuidad de las afectaciones y el desequilibrio de poder son elementos centrales para diferenciar el acoso de un conflicto ocasional.', '["El uso de medios digitales o la existencia de desacuerdos no basta para diferenciar un conflicto ocasional de una situación de acoso.", "La agresión física es importante, pero no constituye el criterio principal para reconocer el patrón previo de persecución.", "La reiteración, la continuidad de las afectaciones y el desequilibrio de poder son elementos centrales para diferenciar el acoso de un conflicto ocasional."]'::jsonb),
    ('elkin-situacion-1', 4, 'elkin-s1-q4', 4, 'Frente a la propuesta del coordinador de reunir a Valeria y Samuel para que expliquen públicamente lo ocurrido, la decisión más adecuada es:', '["Realizar el encuentro únicamente con presencia de las familias, porque su acompañamiento permitiría equilibrar las versiones y evitar nuevos desacuerdos.", "Escuchar inicialmente a los estudiantes por separado, valorar los riesgos y evitar confrontaciones o exposiciones que puedan profundizar la afectación.", "Aplazar el encuentro hasta que el curso haya realizado una reflexión colectiva y pueda acompañar una reconciliación entre los estudiantes involucrados."]'::jsonb, 1, 'Escuchar separadamente, valorar el riesgo y proteger a Valeria permite comprender el caso sin obligarla a enfrentar prematuramente a quien la agredió.', '["La presencia de las familias no elimina el riesgo de presión, confrontación o revictimización de la estudiante afectada.", "Escuchar separadamente, valorar el riesgo y proteger a Valeria permite comprender el caso sin obligarla a enfrentar prematuramente a quien la agredió.", "Una reflexión colectiva no debe realizarse antes de garantizar la protección, la confidencialidad y el análisis individual de los hechos."]'::jsonb),
    ('elkin-situacion-1', 5, 'elkin-s1-q5', 5, 'La institución recibe capturas de pantalla, videos y mensajes relacionados con las agresiones. El manejo pedagógico y responsable de estas evidencias exige:', '["Presentarlas completas ante el curso para mostrar la gravedad de lo sucedido y promover que los estudiantes reconozcan sus responsabilidades.", "Entregarlas a las familias involucradas para que cada una determine cuáles contenidos pueden utilizarse durante las reuniones institucionales.", "Conservarlas de manera segura, limitar su acceso, registrar su procedencia y utilizarlas solo para las actuaciones de protección, atención y seguimiento."]'::jsonb, 2, 'Las evidencias deben conservarse con seguridad, registrar su procedencia y utilizarse únicamente para proteger, atender, esclarecer y hacer seguimiento.', '["Mostrar las evidencias al curso amplía la exposición, puede reproducir el daño y vulnera la privacidad de los involucrados.", "Las familias no deben decidir libremente cómo circular materiales sensibles; la institución debe controlar su manejo y confidencialidad.", "Las evidencias deben conservarse con seguridad, registrar su procedencia y utilizarse únicamente para proteger, atender, esclarecer y hacer seguimiento."]'::jsonb),
    ('elkin-situacion-1', 6, 'elkin-s1-q6', 6, 'Ante la solicitud de expulsión inmediata formulada por la madre de Valeria, el rector debe:', '["Aplicar la expulsión como medida preventiva, debido a que la permanencia de Samuel podría aumentar el temor de Valeria y de su familia.", "Negociar con ambas familias una suspensión prolongada que evite la cancelación de matrícula y permita cerrar el caso institucionalmente.", "Garantizar el debido proceso, valorar la proporcionalidad de las medidas y articular las consecuencias con acciones pedagógicas, protectoras y de seguimiento."]'::jsonb, 2, 'Las medidas deben ser proporcionales, respetar el debido proceso e incluir consecuencias pedagógicas, reparación, protección y seguimiento.', '["La expulsión inmediata desconoce el debido proceso y convierte una solicitud familiar en una decisión automática.", "La suspensión prolongada no debe utilizarse como negociación para cerrar el caso ni sustituye el análisis pedagógico y protector.", "Las medidas deben ser proporcionales, respetar el debido proceso e incluir consecuencias pedagógicas, reparación, protección y seguimiento."]'::jsonb),
    ('elkin-situacion-1', 7, 'elkin-s1-q7', 7, 'El argumento del padre de Samuel según el cual el caso debe cerrarse porque las publicaciones fueron eliminadas es insuficiente porque:', '["La eliminación de los mensajes confirma que los estudiantes involucrados reconocieron la gravedad de las acciones realizadas.", "Las capturas conservadas permiten establecer automáticamente la responsabilidad de cada integrante del grupo de mensajería.", "La desaparición del contenido no elimina las afectaciones ni impide valorar otros registros, testimonios y patrones de repetición."]'::jsonb, 2, 'La eliminación del contenido no borra el daño y el caso puede analizarse mediante testimonios, capturas, videos y patrones de conducta.', '["Eliminar mensajes no constituye por sí mismo reconocimiento de responsabilidad ni garantiza que hayan cesado las afectaciones.", "Las capturas son evidencias relevantes, pero no establecen automáticamente la responsabilidad individual de todas las personas del grupo.", "La eliminación del contenido no borra el daño y el caso puede analizarse mediante testimonios, capturas, videos y patrones de conducta."]'::jsonb),
    ('elkin-situacion-1', 8, 'elkin-s1-q8', 8, 'En el análisis del caso de Valeria, la función más pertinente del Comité Escolar de Convivencia es:', '["Determinar la sanción definitiva, sustituir las decisiones del rector y establecer la responsabilidad individual de cada estudiante.", "Analizar integralmente la situación, coordinar acciones institucionales, promover medidas pedagógicas y realizar seguimiento a los compromisos.", "Remitir el caso a entidades externas para que estas definan las medidas pedagógicas que debe aplicar la institución dentro del curso."]'::jsonb, 1, 'Su función es analizar integralmente, coordinar actuaciones, proponer acciones pedagógicas y verificar el cumplimiento de los compromisos.', '["El comité no reemplaza al rector ni actúa únicamente como órgano sancionador o tribunal disciplinario.", "Su función es analizar integralmente, coordinar actuaciones, proponer acciones pedagógicas y verificar el cumplimiento de los compromisos.", "La remisión externa no libera a la institución de sus responsabilidades pedagógicas, protectoras y de seguimiento."]'::jsonb),
    ('elkin-situacion-1', 9, 'elkin-s1-q9', 9, 'Para intervenir con el grupo de octavo B sin revictimizar a Valeria, la institución debería:', '["Pedir a Valeria que relate su experiencia ante el curso para que sus compañeros comprendan directamente las consecuencias de sus acciones.", "Desarrollar actividades sobre participación de observadores, respeto, ciudadanía digital y reparación, sin exponer información reservada de la estudiante.", "Trabajar únicamente con los autores de las publicaciones, porque vincular al grupo podría ampliar la difusión de los hechos y generar nuevas tensiones."]'::jsonb, 1, 'Se puede trabajar ciudadanía digital, observadores, responsabilidad y reparación sin revelar detalles reservados ni identificar a la estudiante.', '["Pedir a Valeria que relate públicamente lo ocurrido puede revictimizarla y convertir su experiencia en objeto de exposición.", "Se puede trabajar ciudadanía digital, observadores, responsabilidad y reparación sin revelar detalles reservados ni identificar a la estudiante.", "Los observadores y quienes reforzaron las publicaciones también influyeron en la situación y requieren intervención pedagógica."]'::jsonb),
    ('elkin-situacion-1', 10, 'elkin-s1-q10', 10, 'La actuación de la directora de grupo, quien inicialmente interpretó las burlas como bromas, debe ser abordada institucionalmente mediante:', '["El análisis de las señales que no fueron identificadas, la formación docente y el fortalecimiento de procedimientos de detección y registro oportuno.", "La apertura de un proceso disciplinario inmediato, pues cualquier omisión docente convierte al educador en responsable directo de las agresiones posteriores.", "Una recomendación privada para que observe mejor al grupo, evitando incluir el asunto en los procesos de revisión institucional."]'::jsonb, 0, 'La omisión debe convertirse en oportunidad de aprendizaje institucional mediante análisis de señales, formación y fortalecimiento de los registros.', '["La omisión debe convertirse en oportunidad de aprendizaje institucional mediante análisis de señales, formación y fortalecimiento de los registros.", "No toda omisión implica automáticamente responsabilidad disciplinaria directa; primero deben analizarse el contexto y las actuaciones.", "Una recomendación privada resulta insuficiente porque el problema revela debilidades institucionales que pueden repetirse con otros estudiantes."]'::jsonb),
    ('elkin-situacion-1', 11, 'elkin-s1-q11', 11, 'Los mensajes enviados por el conductor a Juliana requieren una actuación diferente a la utilizada en un conflicto escolar porque:', '["Pueden constituir una grave vulneración y una posible conducta delictiva que exige protección inmediata y articulación con autoridades competentes.", "Involucran a un adulto externo, por lo que corresponde exclusivamente a la empresa transportadora investigar y adoptar las decisiones necesarias.", "Ocurrieron fuera de la jornada escolar, de modo que la institución debe orientar a la familia, pero abstenerse de intervenir directamente."]'::jsonb, 0, 'Los mensajes de un adulto con contenido sexual pueden representar una vulneración grave y requieren protección y actuación de autoridades competentes.', '["Los mensajes de un adulto con contenido sexual pueden representar una vulneración grave y requieren protección y actuación de autoridades competentes.", "La responsabilidad no corresponde exclusivamente a la empresa, porque la institución conoce un riesgo que afecta a una estudiante.", "Que los mensajes se produjeran fuera de la jornada no elimina el deber institucional de actuar para protegerla."]'::jsonb),
    ('elkin-situacion-1', 12, 'elkin-s1-q12', 12, 'Cuando Juliana pide que nadie conozca lo sucedido, la respuesta más adecuada de la docente orientadora es:', '["Prometer confidencialidad total para conservar la confianza y esperar a que Juliana autorice cualquier actuación posterior.", "Explicar los límites de la confidencialidad, informar que se compartirán solo los datos necesarios y priorizar las acciones de protección.", "Informar inmediatamente todos los detalles al personal docente para asegurar que la comunidad educativa pueda vigilar al presunto responsable."]'::jsonb, 1, 'La orientadora debe explicar los límites de la confidencialidad y compartir solamente la información indispensable con quienes deban intervenir.', '["Prometer secreto absoluto impediría activar las medidas necesarias para proteger a Juliana frente a un riesgo grave.", "La orientadora debe explicar los límites de la confidencialidad y compartir solamente la información indispensable con quienes deban intervenir.", "Informar todos los detalles al personal docente vulneraría la reserva y ampliaría innecesariamente la circulación de información sensible."]'::jsonb),
    ('elkin-situacion-1', 13, 'elkin-s1-q13', 13, 'Ante el riesgo asociado con el conductor de la ruta escolar, la secuencia institucional más adecuada es:', '["Proteger a Juliana, evitar el contacto con el adulto, conservar las evidencias y activar oportunamente la articulación con las autoridades correspondientes.", "Entrevistar al conductor, comparar su versión con los mensajes y posteriormente decidir si existen elementos suficientes para realizar un reporte externo.", "Citar primero a la tía de Juliana, esperar su autorización escrita y luego definir si la institución puede comunicar el caso a otras entidades."]'::jsonb, 0, 'La secuencia prioriza la seguridad, evita nuevos contactos, conserva las evidencias y activa oportunamente a las autoridades responsables.', '["La secuencia prioriza la seguridad, evita nuevos contactos, conserva las evidencias y activa oportunamente a las autoridades responsables.", "Entrevistar primero al conductor puede alertarlo, aumentar el riesgo y convertir a la institución en investigadora de una posible conducta delictiva.", "La protección no puede depender de una autorización familiar cuando existe una amenaza para la integridad de una menor."]'::jsonb),
    ('elkin-situacion-1', 14, 'elkin-s1-q14', 14, 'La propuesta del rector de realizar una investigación interna antes de informar a las autoridades resulta inadecuada principalmente porque:', '["La institución debe remitir cualquier conflicto a entidades externas y abstenerse de recopilar información o acompañar a los estudiantes involucrados.", "El rector carece de competencia para escuchar a los adultos contratistas, aunque la situación se encuentre relacionada con un servicio escolar.", "La verificación interna no puede retrasar la protección ni sustituir la intervención de las autoridades encargadas de investigar posibles delitos."]'::jsonb, 2, 'Una posible investigación interna no debe retrasar la protección ni reemplazar la actuación de las autoridades encargadas.', '["La institución sí debe escuchar, registrar, acompañar y proteger; lo que no puede es sustituir a las autoridades competentes.", "El problema central no es que el rector carezca totalmente de competencia para comunicarse con el contratista.", "Una posible investigación interna no debe retrasar la protección ni reemplazar la actuación de las autoridades encargadas."]'::jsonb),
    ('elkin-situacion-1', 15, 'elkin-s1-q15', 15, 'Respecto a la comunicación con la familia o persona cuidadora de Juliana, la institución debe:', '["Informar inmediatamente a cualquier familiar disponible, sin considerar la opinión de Juliana ni los riesgos que pueda producir la revelación.", "Valorar quién ejerce su cuidado, informar de manera protectora y coordinar la actuación cuando la comunicación no incremente el riesgo para la estudiante.", "Mantener la información exclusivamente entre Juliana y la orientadora hasta que una autoridad externa indique expresamente que puede comunicarse a la familia."]'::jsonb, 1, 'Debe identificarse al cuidador responsable y valorar que la comunicación contribuya a la protección sin producir nuevos riesgos.', '["Comunicar indiscriminadamente puede aumentar el riesgo, generar culpabilización o afectar la seguridad emocional de Juliana.", "Debe identificarse al cuidador responsable y valorar que la comunicación contribuya a la protección sin producir nuevos riesgos.", "Mantener el caso únicamente entre Juliana y la orientadora impediría activar apoyos familiares e institucionales necesarios."]'::jsonb),
    ('elkin-situacion-1', 16, 'elkin-s1-q16', 16, 'Para evitar la revictimización de Juliana durante las actuaciones posteriores, es fundamental:', '["Solicitar que relate los hechos ante el Comité Escolar de Convivencia para que todos sus integrantes conozcan directamente la situación.", "Realizar entrevistas sucesivas con diferentes profesionales, pues la coincidencia entre los relatos permite establecer con mayor precisión su veracidad.", "Reducir la repetición del relato, utilizar personal competente y compartir únicamente la información necesaria para protegerla y activar la atención."]'::jsonb, 2, 'Se debe limitar la repetición, recurrir a personal competente y compartir solo lo indispensable para proteger y atender.', '["Exponer a Juliana ante el comité para que repita su relato puede generar revictimización y no es necesario para informar las decisiones.", "La repetición sucesiva no garantiza mayor veracidad y puede aumentar el impacto emocional de la experiencia.", "Se debe limitar la repetición, recurrir a personal competente y compartir solo lo indispensable para proteger y atender."]'::jsonb),
    ('elkin-situacion-1', 17, 'elkin-s1-q17', 17, 'Frente a la posibilidad de utilizar estrategias restaurativas en las situaciones presentadas, la institución debe considerar que:', '["Solo proceden cuando son seguras, voluntarias y pertinentes, y no deben emplearse para enfrentar a una estudiante con un adulto señalado por una posible conducta delictiva.", "Deben aplicarse en todos los casos, porque el diálogo directo entre las partes constituye la principal forma de restablecer relaciones y reparar daños.", "Son adecuadas únicamente después de imponer una sanción, incluso cuando la persona afectada manifieste que no desea encontrarse con quien la agredió."]'::jsonb, 0, 'Las prácticas restaurativas requieren voluntariedad, seguridad y pertinencia; no deben forzar encuentros en situaciones de grave vulneración o posible delito.', '["Las prácticas restaurativas requieren voluntariedad, seguridad y pertinencia; no deben forzar encuentros en situaciones de grave vulneración o posible delito.", "El diálogo directo no es apropiado en todos los casos y puede aumentar el desequilibrio o la afectación de la víctima.", "La negativa de la persona afectada debe respetarse; una sanción previa no vuelve obligatorio ni seguro el encuentro."]'::jsonb),
    ('elkin-situacion-1', 18, 'elkin-s1-q18', 18, 'Los registros institucionales de las actuaciones deberían elaborarse de manera que:', '["Incluyan interpretaciones detalladas sobre la personalidad de los estudiantes para facilitar la identificación de posibles responsables futuros.", "Sean conocidos por todos los docentes, aunque no intervengan en el caso, para que puedan controlar el comportamiento de los estudiantes.", "Contengan hechos verificables, decisiones, responsables, tiempos, compromisos y seguimientos, con acceso restringido según la función de cada persona."]'::jsonb, 2, 'Un registro adecuado describe hechos, decisiones, responsables, tiempos, compromisos y seguimiento, manteniendo acceso restringido.', '["Registrar juicios sobre la personalidad produce estigmatización y reemplaza los hechos verificables por interpretaciones subjetivas.", "La información sensible no debe quedar disponible para todo el personal, sino únicamente para quienes intervienen legítimamente.", "Un registro adecuado describe hechos, decisiones, responsables, tiempos, compromisos y seguimiento, manteniendo acceso restringido."]'::jsonb),
    ('elkin-situacion-1', 19, 'elkin-s1-q19', 19, 'Cuando Valeria informa que algunos compañeros la llaman “sapa” y han dejado de hablarle, la institución debe entender que:', '["Se trata de una reacción social esperable que disminuirá cuando el grupo deje de hablar sobre las publicaciones anteriores.", "Es una dificultad de integración que debe resolverse principalmente fortaleciendo las habilidades sociales de Valeria.", "Pueden ser nuevas formas de agresión o retaliación que exigen revisar el nivel de riesgo, ajustar las medidas de protección y continuar el seguimiento."]'::jsonb, 2, 'Los insultos y la exclusión pueden constituir retaliación, por lo que deben revisarse el riesgo y las medidas de protección.', '["Las expresiones y el aislamiento no deben normalizarse como una reacción esperable, pues pueden prolongar la agresión.", "Centrar la respuesta en las habilidades sociales de Valeria trasladaría a la víctima la responsabilidad de resolver el problema.", "Los insultos y la exclusión pueden constituir retaliación, por lo que deben revisarse el riesgo y las medidas de protección."]'::jsonb),
    ('elkin-situacion-1', 20, 'elkin-s1-q20', 20, 'La intervención más formativa con Samuel debería integrar:', '["Reconocimiento del daño, responsabilidad por sus decisiones, trabajo con la familia, desarrollo de habilidades y seguimiento de cambios observables.", "Elaboración de actividades escritas sobre respeto, cumplimiento de una suspensión y compromiso de no volver a utilizar grupos virtuales.", "Separación permanente de Valeria, restricción de su participación escolar y revisión periódica de su comportamiento disciplinario."]'::jsonb, 0, 'Una intervención formativa debe promover reconocimiento del daño, responsabilidad, habilidades sociales, participación familiar y seguimiento de cambios reales.', '["Una intervención formativa debe promover reconocimiento del daño, responsabilidad, habilidades sociales, participación familiar y seguimiento de cambios reales.", "Las actividades escritas y la suspensión pueden ser insuficientes si no modifican la comprensión ni la conducta del estudiante.", "La separación permanente y la restricción general de participación pueden ser desproporcionadas y no garantizan aprendizaje ni reparación."]'::jsonb),
    ('elkin-situacion-1', 21, 'elkin-s1-q21', 21, 'Para determinar si las acciones adoptadas están mejorando la convivencia, el Comité debería:', '["Verificar únicamente si Samuel cumplió las actividades asignadas y si se eliminaron definitivamente las publicaciones digitales.", "Analizar recurrencia de agresiones, percepción de seguridad, asistencia, participación, cumplimiento de acuerdos y aparición de retaliaciones.", "Aplicar una encuesta general de satisfacción al finalizar el periodo y comparar los resultados con las calificaciones de comportamiento."]'::jsonb, 1, 'El seguimiento debe analizar recurrencia, percepción de seguridad, asistencia, participación, acuerdos y posibles retaliaciones.', '["Cumplir actividades o eliminar publicaciones no permite saber si realmente cesaron las agresiones y mejoró la seguridad.", "El seguimiento debe analizar recurrencia, percepción de seguridad, asistencia, participación, acuerdos y posibles retaliaciones.", "Una encuesta general y las notas de comportamiento ofrecen información limitada y no sustituyen el seguimiento específico."]'::jsonb),
    ('elkin-situacion-1', 22, 'elkin-s1-q22', 22, 'La actualización del manual de convivencia debería realizarse mediante un proceso que:', '["Fortalezca principalmente el listado de faltas y sanciones para que los docentes puedan actuar con rapidez ante cualquier comportamiento inadecuado.", "Sea elaborado por el rector y el coordinador, pues la participación de estudiantes y familias puede dificultar la precisión de los procedimientos.", "Diferencie situaciones, establezca protocolos, garantice derechos, incorpore medidas pedagógicas y cuente con participación de la comunidad educativa."]'::jsonb, 2, 'El manual debe diferenciar situaciones, establecer protocolos, garantizar derechos e integrar medidas pedagógicas construidas participativamente.', '["Un manual centrado en faltas y sanciones no garantiza prevención, atención, protección ni formación para la convivencia.", "La actualización no debe quedar exclusivamente en manos de directivos; requiere participación de la comunidad educativa.", "El manual debe diferenciar situaciones, establecer protocolos, garantizar derechos e integrar medidas pedagógicas construidas participativamente."]'::jsonb),
    ('elkin-situacion-1', 23, 'elkin-s1-q23', 23, 'Si la familia de Samuel se niega a asistir a las reuniones y rechaza los compromisos propuestos, la institución debe:', '["Suspender las actuaciones hasta lograr la presencia de la familia, porque sin su autorización no pueden desarrollarse medidas pedagógicas.", "Documentar la negativa, mantener la protección, continuar el debido proceso y utilizar otros canales institucionales para promover la corresponsabilidad.", "Aplicar automáticamente la medida más grave establecida en el manual, debido al incumplimiento de la familia frente a las citaciones."]'::jsonb, 1, 'La institución debe documentar la negativa, mantener las actuaciones y utilizar otros medios para promover la corresponsabilidad familiar.', '["La ausencia de la familia no suspende la obligación institucional de proteger, intervenir y continuar el debido proceso.", "La institución debe documentar la negativa, mantener las actuaciones y utilizar otros medios para promover la corresponsabilidad familiar.", "La inasistencia de la familia no autoriza automáticamente la sanción más grave contra el estudiante."]'::jsonb),
    ('elkin-situacion-1', 24, 'elkin-s1-q24', 24, 'El principal aprendizaje institucional derivado de los casos de Valeria y Juliana es que la convivencia escolar requiere:', '["Concentrar los esfuerzos en sancionar con mayor firmeza, porque la claridad de las consecuencias evita que las situaciones vuelvan a ocurrir.", "Delegar los casos complejos en la docente orientadora, quien posee la formación especializada para atender las vulneraciones escolares.", "Articular promoción, prevención, atención y seguimiento, fortaleciendo capacidades institucionales y coordinando la protección con otros actores."]'::jsonb, 2, 'La institución debe articular promoción, prevención, atención y seguimiento, además de coordinarse con actores externos cuando sea necesario.', '["Una respuesta centrada en sanciones desconoce los componentes preventivos, formativos, protectores y de seguimiento.", "La convivencia no puede delegarse exclusivamente en la orientadora; compromete a toda la comunidad educativa.", "La institución debe articular promoción, prevención, atención y seguimiento, además de coordinarse con actores externos cuando sea necesario."]'::jsonb),
    ('elkin-situacion-1', 25, 'elkin-s1-q25', 25, 'El plan institucional más sólido frente a la situación descrita sería aquel que:', '["Mantenga la protección individual, active las instancias correspondientes, intervenga pedagógicamente con el grupo, fortalezca el manual, capacite al personal y evalúe resultados mediante seguimiento continuo.", "Resuelva cada caso mediante acuerdos familiares, sanciones proporcionales y campañas generales, evitando involucrar actores externos mientras existan posibilidades de solución institucional.", "Priorice la actualización documental, la aplicación uniforme de sanciones y la centralización de los casos en el Comité Escolar de Convivencia para asegurar decisiones consistentes."]'::jsonb, 0, 'Integra protección, actuación institucional, intervención pedagógica, formación, revisión de procedimientos y seguimiento continuo.', '["Integra protección, actuación institucional, intervención pedagógica, formación, revisión de procedimientos y seguimiento continuo.", "Evitar actores externos puede incumplir la obligación de activar autoridades cuando la naturaleza de la situación lo exige.", "Actualizar documentos y uniformar sanciones no resuelve por sí solo las necesidades de protección, formación y seguimiento."]'::jsonb),
    ('elkin-situacion-2', 26, 'elkin-s2-q1', 26, 'Ante la solicitud de matrícula de Mariana, la actuación institucional más pertinente es:', '["Reservar temporalmente el cupo hasta que la familia presente una certificación actualizada que permita definir los apoyos que la institución puede ofrecer.", "Matricularla en el grado al que fue promovida e iniciar la valoración pedagógica y la identificación de barreras y apoyos con la información disponible.", "Ubicarla provisionalmente en un grado inferior mientras los docentes determinan si su desempeño corresponde a las exigencias académicas de séptimo."]'::jsonb, 1, 'Debe reconocerse la promoción previa, matricular a Mariana en séptimo e iniciar la valoración pedagógica con la información disponible.', '["La matrícula y los apoyos no pueden condicionarse a la presentación de una certificación médica actualizada.", "Debe reconocerse la promoción previa, matricular a Mariana en séptimo e iniciar la valoración pedagógica con la información disponible.", "Ubicarla en un grado inferior desconoce su trayectoria y utiliza la discapacidad como criterio anticipado de retroceso escolar."]'::jsonb),
    ('elkin-situacion-2', 27, 'elkin-s2-q2', 27, 'La interpretación más adecuada de las dificultades que enfrenta Mariana en la institución es que:', '["Se originan principalmente en su condición motora, que limita el cumplimiento de las actividades diseñadas para el nivel educativo en el que fue matriculada.", "Se explican por la falta de un profesional permanente que pueda compensar las limitaciones de la estudiante durante las clases y las evaluaciones.", "Surgen de la interacción entre sus características y las barreras físicas, pedagógicas, comunicativas, tecnológicas y actitudinales del entorno escolar."]'::jsonb, 2, 'Las dificultades surgen de la interacción entre sus características y las barreras físicas, pedagógicas, tecnológicas, comunicativas y actitudinales.', '["Atribuir las dificultades exclusivamente a Mariana ignora las condiciones del entorno que limitan su aprendizaje y participación.", "La falta de un profesional permanente no explica por sí sola las barreras ni elimina la responsabilidad de los docentes.", "Las dificultades surgen de la interacción entre sus características y las barreras físicas, pedagógicas, tecnológicas, comunicativas y actitudinales."]'::jsonb),
    ('elkin-situacion-2', 28, 'elkin-s2-q3', 28, 'La acción inicial más pertinente para construir los apoyos requeridos por Mariana es:', '["Integrar la información escolar disponible con la valoración pedagógica, la observación, la participación de Mariana y los aportes de su familia y docentes.", "Esperar el concepto actualizado de los especialistas para definir con precisión las actividades que puede o no puede desarrollar en cada área.", "Aplicar sin modificaciones las estrategias utilizadas por el colegio anterior, dado que ya fueron probadas durante su trayectoria educativa."]'::jsonb, 0, 'La valoración debe integrar documentos, observaciones, producciones, diálogo con Mariana, información familiar y aportes docentes.', '["La valoración debe integrar documentos, observaciones, producciones, diálogo con Mariana, información familiar y aportes docentes.", "Esperar especialistas retrasaría los apoyos y subordinaría las decisiones pedagógicas a un diagnóstico clínico.", "Las estrategias anteriores pueden orientar, pero deben revisarse según el nuevo contexto y las barreras actuales."]'::jsonb),
    ('elkin-situacion-2', 29, 'elkin-s2-q4', 29, 'Respecto a la elaboración y aplicación del plan individual de Mariana, la distribución más adecuada de responsabilidades consiste en:', '["Encargar a la docente de apoyo de diseñar las actividades y evaluaciones, mientras los docentes de área aplican las orientaciones recibidas.", "Permitir que cada docente determine los ajustes de su asignatura y remita periódicamente los resultados a la docente de apoyo para su validación.", "Construir acuerdos colaborativos, manteniendo en los docentes de aula la responsabilidad de planear, enseñar, evaluar y hacer seguimiento con el acompañamiento requerido."]'::jsonb, 2, 'La construcción es colaborativa, pero la responsabilidad pedagógica permanece en los docentes con el acompañamiento necesario.', '["La docente de apoyo no reemplaza a los docentes de área en la planeación, enseñanza y evaluación.", "Los ajustes no deben depender de decisiones aisladas ni de una validación posterior de la docente de apoyo.", "La construcción es colaborativa, pero la responsabilidad pedagógica permanece en los docentes con el acompañamiento necesario."]'::jsonb),
    ('elkin-situacion-2', 30, 'elkin-s2-q5', 30, 'La relación más adecuada entre las estrategias generales de accesibilidad y los ajustes individuales consiste en:', '["Diseñar primero actividades específicas para Mariana y, cuando resulten exitosas, aplicarlas progresivamente a los demás estudiantes del curso.", "Mantener una planeación común y realizar modificaciones únicamente cuando la familia demuestre que la estudiante no puede responder a ella.", "Diseñar desde el comienzo múltiples formas de acceso, participación y expresión para todo el grupo, incorporando apoyos específicos cuando persistan barreras particulares."]'::jsonb, 2, 'La planeación debe ofrecer múltiples formas de acceso y expresión para todos, complementadas con ajustes individuales cuando sean necesarios.', '["Diseñar inicialmente actividades separadas puede mantener la segregación y limitar el acceso al currículo común.", "La familia no tiene que demostrar primero el fracaso de una planeación antes de que se eliminen las barreras.", "La planeación debe ofrecer múltiples formas de acceso y expresión para todos, complementadas con ajustes individuales cuando sean necesarios."]'::jsonb),
    ('elkin-situacion-2', 31, 'elkin-s2-q6', 31, 'Frente a las actividades simplificadas propuestas en Lengua Castellana, la decisión pedagógica más adecuada es:', '["Mantener propósitos de aprendizaje significativos y ofrecer formas accesibles para analizar, producir y comunicar textos sin reducirla a tareas ajenas a las competencias del grado.", "Aplicar las mismas actividades manuscritas del grupo, ampliando exclusivamente el tiempo de respuesta para conservar la igualdad de exigencias.", "Continuar con contenidos de grados inferiores hasta que Mariana demuestre suficiente velocidad de escritura y expresión oral para integrarse a las actividades comunes."]'::jsonb, 0, 'Deben conservarse aprendizajes significativos del grado y modificar las formas de acceso, participación y producción.', '["Deben conservarse aprendizajes significativos del grado y modificar las formas de acceso, participación y producción.", "Ampliar solamente el tiempo no elimina las barreras de copia, escritura manual y comunicación.", "Mantenerla en contenidos inferiores reduce expectativas y no reconoce sus competencias reales."]'::jsonb),
    ('elkin-situacion-2', 32, 'elkin-s2-q7', 32, 'La propuesta de limitar anticipadamente la calificación máxima de Mariana a 3,5 debe considerarse:', '["Inadecuada, porque establece un límite basado en su condición y no en evidencias sobre el nivel real de las competencias evaluadas.", "Pertinente de manera provisional, mientras la institución reúne información suficiente para determinar si los ajustes modifican la exigencia académica.", "Aceptable si la estudiante desarrolla actividades diferentes, pues la escala debe reflejar que no respondió a los mismos instrumentos utilizados por el grupo."]'::jsonb, 0, 'Una calificación máxima anticipada discrimina y desconoce que el desempeño debe valorarse a partir de evidencias de aprendizaje.', '["Una calificación máxima anticipada discrimina y desconoce que el desempeño debe valorarse a partir de evidencias de aprendizaje.", "No existe justificación para limitar provisionalmente la escala mientras se reúnen nuevas evidencias.", "Utilizar instrumentos diferentes no significa reducir el nivel de logro ni impedir una valoración superior."]'::jsonb),
    ('elkin-situacion-2', 33, 'elkin-s2-q8', 33, 'La evaluación desarrollada por el profesor de Matemáticas resulta pertinente principalmente porque:', '["reduce la complejidad de los problemas y compensa las limitaciones de Mariana mediante herramientas que facilitan la obtención de respuestas correctas.", "conserva las competencias evaluadas y permite demostrar su comprensión mediante recursos, tiempos y formas de respuesta acordes con sus necesidades.", "reemplaza la evaluación escrita por una presentación digital, evitando que la dificultad motora incida en cualquier componente de la valoración."]'::jsonb, 1, 'Se mantuvieron las competencias y criterios, pero se ofrecieron recursos y tiempos que permitieron demostrar la comprensión.', '["El profesor no disminuyó la complejidad central de los problemas ni facilitó automáticamente las respuestas.", "Se mantuvieron las competencias y criterios, pero se ofrecieron recursos y tiempos que permitieron demostrar la comprensión.", "La presentación digital no elimina todas las exigencias; es una forma accesible de expresar el procedimiento y la argumentación."]'::jsonb),
    ('elkin-situacion-2', 34, 'elkin-s2-q9', 34, 'Ante la inaccesibilidad del laboratorio de ciencias, la respuesta institucional más adecuada es:', '["asignar a Mariana una actividad teórica equivalente mientras se realizan las adecuaciones físicas necesarias para acceder al segundo piso.", "suspender temporalmente las prácticas experimentales del grupo para garantizar que ningún estudiante reciba oportunidades diferentes.", "reorganizar espacios, materiales, roles y condiciones de seguridad para asegurar su participación, mientras se gestionan soluciones permanentes de accesibilidad."]'::jsonb, 2, 'Deben reorganizarse temporalmente los espacios y materiales mientras se gestionan soluciones permanentes de accesibilidad.', '["Una guía teórica no ofrece las mismas oportunidades de experimentación, formulación de hipótesis y trabajo colaborativo.", "Suspender las prácticas del grupo no constituye una solución necesaria ni proporcional.", "Deben reorganizarse temporalmente los espacios y materiales mientras se gestionan soluciones permanentes de accesibilidad."]'::jsonb),
    ('elkin-situacion-2', 35, 'elkin-s2-q10', 35, 'En Educación Física, la actuación más pertinente del docente es:', '["sustituir las actividades prácticas por trabajos conceptuales, dado que estos permiten evaluar conocimientos deportivos sin poner en riesgo a la estudiante.", "adaptar actividades, implementos, espacios y criterios de evaluación para valorar su participación, progreso, autonomía y desarrollo corporal.", "asignar una valoración basada en asistencia, disposición y cumplimiento, evitando comparar su desempeño físico con el del resto del grupo."]'::jsonb, 1, 'Las actividades deben adaptarse para valorar participación, progreso, autonomía y desarrollo corporal de manera segura.', '["Sustituir toda la práctica por teoría excluye a Mariana de experiencias corporales que puede desarrollar con apoyos.", "Las actividades deben adaptarse para valorar participación, progreso, autonomía y desarrollo corporal de manera segura.", "Calificar únicamente asistencia y disposición reduciría las expectativas y no permitiría evaluar aprendizajes propios del área."]'::jsonb),
    ('elkin-situacion-2', 36, 'elkin-s2-q11', 36, 'Frente a las barreras de la plataforma digital, la institución debe:', '["ofrecer alternativas accesibles inmediatas y revisar la plataforma para eliminar progresivamente los obstáculos que limitan el acceso y la entrega autónoma de actividades.", "solicitar a la familia que descargue, imprima y entregue los trabajos, mientras la institución consigue recursos tecnológicos especializados.", "mantener los mismos contenidos digitales y ampliar los plazos, puesto que la flexibilidad temporal compensa las dificultades de acceso al sistema."]'::jsonb, 0, 'La institución debe ofrecer alternativas inmediatas y mejorar progresivamente la accesibilidad de la plataforma.', '["La institución debe ofrecer alternativas inmediatas y mejorar progresivamente la accesibilidad de la plataforma.", "Imprimir todo traslada la barrera y los costos a la familia sin corregir el problema institucional.", "Ampliar plazos no resuelve botones pequeños, documentos inaccesibles ni dificultades de navegación."]'::jsonb),
    ('elkin-situacion-2', 37, 'elkin-s2-q12', 37, 'La revisión del sistema institucional de evaluación debe realizarse mediante un proceso que:', '["sea liderado por el rector y el coordinador, quienes pueden modificar los criterios después de consultar a los docentes que atienden estudiantes con discapacidad.", "incorpore un capítulo especial aplicable únicamente a los estudiantes que cuenten con certificación y plan individual formalizado.", "vincule a la comunidad educativa, sea analizado y aprobado por las instancias correspondientes, se articule al proyecto institucional y se divulgue oportunamente."]'::jsonb, 2, 'La revisión debe ser participativa, institucionalmente aprobada, articulada al proyecto educativo y comunicada a la comunidad.', '["La modificación no debe ser exclusiva de directivos ni limitarse a una consulta informal con docentes.", "La inclusión y la evaluación flexible no corresponden únicamente a estudiantes certificados.", "La revisión debe ser participativa, institucionalmente aprobada, articulada al proyecto educativo y comunicada a la comunidad."]'::jsonb),
    ('elkin-situacion-2', 38, 'elkin-s2-q13', 38, 'Ante la solicitud de la madre de promover automáticamente a Mariana, la institución debe:', '["explicar que la promoción no es automática y debe fundamentarse en los criterios institucionales, las competencias desarrolladas, los ajustes implementados y su trayectoria educativa.", "aceptar la solicitud para evitar que la discapacidad y las ausencias médicas se conviertan en causas de repitencia o deserción.", "aplicar sin modificaciones los criterios generales de promoción, pues cualquier consideración particular podría producir un trato desigual frente al grupo."]'::jsonb, 0, 'La discapacidad no genera promoción automática; la decisión debe fundamentarse en evidencias, apoyos, ajustes y trayectoria.', '["La discapacidad no genera promoción automática; la decisión debe fundamentarse en evidencias, apoyos, ajustes y trayectoria.", "Promover sin valorar competencias puede desconocer el carácter formativo y objetivo de la evaluación.", "Aplicar criterios sin considerar las barreras y los ajustes puede producir una igualdad formal, pero injusta."]'::jsonb),
    ('elkin-situacion-2', 39, 'elkin-s2-q14', 39, 'Frente al porcentaje de inasistencia superado por Mariana, la decisión más pertinente es:', '["aplicar el criterio institucional de manera automática, ya que las causas justificadas explican la ausencia, pero no reemplazan el tiempo escolar perdido.", "excluir todas las ausencias médicas del cálculo, debido a que ninguna situación relacionada con salud puede incidir en una decisión de promoción.", "analizar las causas, los apoyos ofrecidos, las oportunidades de aprendizaje, las evidencias disponibles y los ajustes requeridos antes de decidir su efecto en la promoción."]'::jsonb, 2, 'La decisión debe considerar causas, apoyos, evidencias, oportunidades de recuperación y condiciones particulares del proceso.', '["Una regla automática de inasistencia desconoce las causas justificadas y las oportunidades reales de aprendizaje.", "Excluir todas las ausencias médicas sin análisis tampoco permite valorar la trayectoria ni los aprendizajes alcanzados.", "La decisión debe considerar causas, apoyos, evidencias, oportunidades de recuperación y condiciones particulares del proceso."]'::jsonb),
    ('elkin-situacion-2', 40, 'elkin-s2-q15', 40, 'La alta ponderación de pruebas escritas cronometradas plantea un problema en el proceso de Mariana porque:', '["obliga a concederle más tiempo que al resto del grupo y puede alterar la equivalencia matemática de las calificaciones obtenidas.", "puede hacer que la valoración dependa de su velocidad motora y no de las competencias, por lo que deben diversificarse los instrumentos y las evidencias.", "impide utilizar el plan individual como principal criterio de calificación, aunque este debería reemplazar los porcentajes comunes establecidos para el área."]'::jsonb, 1, 'Las pruebas pueden terminar evaluando velocidad motora en lugar de aprendizajes, por lo que deben diversificarse los instrumentos.', '["El problema no consiste en que Mariana reciba más tiempo, sino en qué competencia mide realmente la prueba.", "Las pruebas pueden terminar evaluando velocidad motora en lugar de aprendizajes, por lo que deben diversificarse los instrumentos.", "El plan individual orienta ajustes, pero no reemplaza automáticamente todos los criterios institucionales de evaluación."]'::jsonb),
    ('elkin-situacion-2', 41, 'elkin-s2-q16', 41, 'Las estrategias destinadas a superar las dificultades de aprendizaje deberían:', '["concentrarse al finalizar cada periodo, cuando ya exista suficiente información para identificar los desempeños que no fueron alcanzados.", "ser desarrolladas principalmente por la familia mediante actividades complementarias que compensen el tiempo limitado de las clases.", "implementarse de manera permanente, con seguimiento, retroalimentación y reorientación de las prácticas antes de que las dificultades se acumulen."]'::jsonb, 2, 'Los apoyos deben ser continuos, retroalimentar la enseñanza y ajustarse según los avances y dificultades observados.', '["Esperar al final del periodo permite que las dificultades se acumulen y reduce la capacidad preventiva de la evaluación.", "La familia puede acompañar, pero la institución conserva la responsabilidad principal sobre la enseñanza y el apoyo pedagógico.", "Los apoyos deben ser continuos, retroalimentar la enseñanza y ajustarse según los avances y dificultades observados."]'::jsonb),
    ('elkin-situacion-2', 42, 'elkin-s2-q17', 42, 'Ante las bajas calificaciones de Lengua Castellana obtenidas mediante actividades de copia, la institución debería:', '["conservar los resultados y agregar nuevas actividades, pues modificar valoraciones anteriores afectaría la estabilidad del proceso evaluativo.", "revisar la validez de las evidencias, aplicar formas accesibles de valoración y determinar si las calificaciones reflejan las competencias o las barreras del instrumento.", "sustituir las valoraciones académicas por una apreciación de su esfuerzo, participación y cumplimiento del plan individual durante el periodo."]'::jsonb, 1, 'Debe revisarse si las notas representan competencias comunicativas o solamente dificultades relacionadas con la escritura manual.', '["Mantener resultados obtenidos mediante instrumentos inválidos perpetuaría la barrera y una valoración poco objetiva.", "Debe revisarse si las notas representan competencias comunicativas o solamente dificultades relacionadas con la escritura manual.", "El esfuerzo es relevante, pero no sustituye la valoración de los aprendizajes alcanzados."]'::jsonb),
    ('elkin-situacion-2', 43, 'elkin-s2-q18', 43, 'Al finalizar el año, la forma más adecuada de informar el proceso de Mariana es:', '["entregarle un boletín diferente al de sus compañeros, estructurado exclusivamente con las metas y los ajustes registrados en su plan individual.", "presentar los mismos informes institucionales y anexar un reporte de competencias, avances, apoyos y recomendaciones cuando existan ajustes particulares de evaluación.", "reemplazar el boletín por un informe conjunto elaborado por la docente de apoyo y los profesionales de salud que conocen su condición."]'::jsonb, 1, 'Mariana debe recibir los informes institucionales y, cuando corresponda, un anexo sobre competencias, ajustes, avances y recomendaciones.', '["Un boletín completamente diferente puede separar innecesariamente su proceso del sistema institucional común.", "Mariana debe recibir los informes institucionales y, cuando corresponda, un anexo sobre competencias, ajustes, avances y recomendaciones.", "Los profesionales de salud no reemplazan a los docentes en la elaboración de los informes académicos."]'::jsonb),
    ('elkin-situacion-2', 44, 'elkin-s2-q19', 44, 'La historia escolar de Mariana debe:', '["permanecer disponible para todos los docentes y funcionarios, de manera que cualquier integrante de la institución pueda anticipar sus necesidades.", "contener únicamente los planes individuales y los informes clínicos, evitando registrar apreciaciones pedagógicas que puedan cambiar con el tiempo.", "conservar de forma confidencial los planes, seguimientos, acuerdos, informes y demás información relevante para garantizar la continuidad de los apoyos."]'::jsonb, 2, 'Debe conservarse confidencialmente la información relevante para garantizar continuidad y coherencia en los apoyos.', '["La información personal no debe estar disponible para cualquiera, sino para quienes la requieran legítimamente.", "La historia escolar también necesita información pedagógica, seguimientos, acuerdos y apoyos efectivos.", "Debe conservarse confidencialmente la información relevante para garantizar continuidad y coherencia en los apoyos."]'::jsonb),
    ('elkin-situacion-2', 45, 'elkin-s2-q20', 45, 'Si Mariana se traslada a otro establecimiento después de ser promovida, la institución receptora debe:', '["realizar una evaluación diagnóstica y ubicarla en un grado inferior cuando identifique diferencias frente a las exigencias académicas institucionales.", "matricularla en el grado promovido, pero esperar una nueva valoración especializada antes de continuar con los ajustes definidos previamente.", "matricularla en el grado correspondiente, utilizar la valoración diagnóstica para organizar apoyos y dar continuidad a la información pedagógica y los ajustes requeridos."]'::jsonb, 2, 'La institución receptora debe respetar el grado promovido y utilizar la información disponible para organizar apoyos.', '["Una evaluación diagnóstica no debe utilizarse para desconocer la promoción ni justificar automáticamente un grado inferior.", "La continuidad de los apoyos no debe suspenderse mientras se espera una nueva valoración especializada.", "La institución receptora debe respetar el grado promovido y utilizar la información disponible para organizar apoyos."]'::jsonb),
    ('elkin-situacion-2', 46, 'elkin-s2-q21', 46, 'Si después de un proceso integral la institución determina que Mariana no debe ser promovida, deberá:', '["garantizar su cupo, construir un plan de apoyo y revisar las condiciones pedagógicas necesarias para que continúe su trayectoria educativa.", "recomendar su traslado a una institución especializada, puesto que la repitencia demostraría que la oferta general no responde a sus necesidades.", "permitir que repita el grado bajo las mismas condiciones, para comprobar si un año adicional mejora su desempeño sin requerir nuevos ajustes."]'::jsonb, 0, 'Si no es promovida, deben garantizarse continuidad, cupo y un plan que transforme las condiciones pedagógicas.', '["Si no es promovida, deben garantizarse continuidad, cupo y un plan que transforme las condiciones pedagógicas.", "La no promoción no demuestra que deba ser remitida a una institución especializada.", "Repetir bajo las mismas condiciones mantendría las barreras que pudieron contribuir a las dificultades."]'::jsonb),
    ('elkin-situacion-2', 47, 'elkin-s2-q22', 47, 'Ante una reclamación formal de la familia sobre evaluación y promoción, la actuación institucional adecuada es:', '["aplicar los procedimientos establecidos, responder oportunamente y permitir que la instancia directiva competente decida cuando no se resuelva en los niveles anteriores.", "remitir inmediatamente la reclamación a la secretaría de educación, ya que la participación de docentes y directivos podría afectar la imparcialidad.", "mantener la decisión del docente de área, salvo que este reconozca voluntariamente que utilizó un instrumento contrario a los acuerdos institucionales."]'::jsonb, 0, 'La reclamación debe seguir los procedimientos institucionales, recibir respuesta oportuna y avanzar a las instancias correspondientes.', '["La reclamación debe seguir los procedimientos institucionales, recibir respuesta oportuna y avanzar a las instancias correspondientes.", "No es necesario remitir inmediatamente todo desacuerdo a la secretaría de educación.", "La decisión docente no es inmodificable y debe someterse a los procedimientos y criterios institucionales."]'::jsonb),
    ('elkin-situacion-2', 48, 'elkin-s2-q23', 48, 'El análisis periódico de los informes de evaluación debería utilizarse para:', '["comparar los resultados de los estudiantes con discapacidad y establecer cuáles requieren apoyos más especializados fuera de la institución.", "identificar prácticas, instrumentos o barreras que estén afectando los desempeños y realizar modificaciones en la enseñanza, la evaluación y el mejoramiento institucional.", "verificar el cumplimiento de los porcentajes y escalas institucionales antes de consolidar los datos que se reportarán a las autoridades educativas."]'::jsonb, 1, 'Los resultados deben utilizarse para identificar barreras, revisar instrumentos y ajustar las prácticas pedagógicas.', '["El propósito no es clasificar estudiantes para enviarlos fuera de la institución.", "Los resultados deben utilizarse para identificar barreras, revisar instrumentos y ajustar las prácticas pedagógicas.", "Verificar porcentajes y reportes administrativos no constituye el objetivo principal del análisis evaluativo."]'::jsonb),
    ('elkin-situacion-2', 49, 'elkin-s2-q24', 49, 'La decisión más sólida sobre la promoción de Mariana sería aquella que:', '["priorice la permanencia escolar y el riesgo de deserción, aun cuando no existan evidencias suficientes sobre las competencias fundamentales del grado.", "integre evidencias accesibles, competencias desarrolladas, trayectoria, proyecto de vida, ajustes realmente implementados, apoyos ofrecidos y posibles efectos de la repitencia.", "aplique los mismos promedios y porcentajes establecidos para todos, considerando que los ajustes modifican la forma de responder, pero no pueden influir en la promoción."]'::jsonb, 1, 'La decisión debe integrar evidencias accesibles, trayectoria, competencias, apoyos aplicados y posibles efectos de la repitencia.', '["Promover solo por permanencia o riesgo de deserción puede ignorar los aprendizajes fundamentales.", "La decisión debe integrar evidencias accesibles, trayectoria, competencias, apoyos aplicados y posibles efectos de la repitencia.", "Aplicar promedios sin considerar la validez de los instrumentos y los ajustes puede consolidar una valoración injusta."]'::jsonb),
    ('elkin-situacion-2', 50, 'elkin-s2-q25', 50, 'El plan institucional que responde de manera más completa a las dificultades identificadas es aquel que:', '["articula accesibilidad, planeación para la diversidad, ajustes individuales, evaluación formativa, revisión del sistema institucional, formación docente, participación familiar y seguimiento a resultados.", "concentra los esfuerzos en perfeccionar el plan individual de Mariana, adquirir tecnología especializada y asignar a la docente de apoyo la coordinación de todas las evaluaciones.", "crea criterios de evaluación y promoción diferenciados para estudiantes con discapacidad, reduce los contenidos obligatorios y establece actividades separadas que faciliten su permanencia."]'::jsonb, 0, 'Integra accesibilidad, evaluación formativa, planeación diversa, ajustes individuales, formación docente y seguimiento institucional.', '["Integra accesibilidad, evaluación formativa, planeación diversa, ajustes individuales, formación docente y seguimiento institucional.", "Centrar todo en Mariana y en la docente de apoyo impide transformar las prácticas generales de la institución.", "Crear criterios reducidos o actividades separadas puede institucionalizar bajas expectativas y segregación."]'::jsonb),
    ('elkin-situacion-3', 51, 'elkin-s3-q1', 51, 'Ante el comentario inicial de Marcela sobre la propuesta de preescolar, la actuación más adecuada de Daniel es:', '["Solicitar a Marcela que retire su comentario y continuar con la agenda para evitar que una diferencia personal retrase la planeación.", "Recuperar el propósito común, reconocer los aportes de cada nivel y promover que las propuestas se analicen mediante criterios compartidos.", "Permitir que Laura y Marcela defiendan sus posiciones hasta que el equipo determine cuál propuesta tiene mayor valor académico."]'::jsonb, 1, 'Daniel orienta al equipo hacia metas comunes, reconoce los aportes de cada nivel y favorece una discusión pedagógica respetuosa.', '["Exigir que Marcela retire el comentario puede detener momentáneamente la tensión, pero no construye comprensión ni visión compartida.", "Daniel orienta al equipo hacia metas comunes, reconoce los aportes de cada nivel y favorece una discusión pedagógica respetuosa.", "Permitir una confrontación prolongada puede profundizar las posiciones personales y alejar al equipo del propósito institucional."]'::jsonb),
    ('elkin-situacion-3', 52, 'elkin-s3-q2', 52, 'Cuando Laura recibe observaciones sobre la claridad de sus materiales de planeación, la respuesta que mejor favorece el trabajo institucional es:', '["explicar que las actividades de preescolar tienen características particulares y que corresponde a los demás docentes adaptarse a su forma de presentarlas.", "mantener los materiales originales y acompañarlos con una explicación verbal durante cada reunión para evitar interpretaciones equivocadas.", "solicitar ejemplos concretos de las dificultades, escuchar las necesidades del equipo y mejorar los materiales sin renunciar al sentido pedagógico de su propuesta."]'::jsonb, 2, 'Escuchar, pedir ejemplos y mejorar la comunicación demuestra apertura, asertividad y disposición para aprender de la retroalimentación.', '["Pedir que los demás se adapten unilateralmente dificulta la colaboración y desconoce necesidades legítimas del equipo.", "Explicar siempre los materiales oralmente no corrige su falta de claridad ni favorece el trabajo autónomo.", "Escuchar, pedir ejemplos y mejorar la comunicación demuestra apertura, asertividad y disposición para aprender de la retroalimentación."]'::jsonb),
    ('elkin-situacion-3', 53, 'elkin-s3-q3', 53, 'Si Marcela identifica que sus compromisos con grado undécimo coinciden con tareas del proyecto, la actuación más responsable es:', '["comunicar oportunamente la situación, proponer alternativas y acordar una redistribución que permita cumplir los compromisos institucionales.", "priorizar las actividades académicas de grado undécimo y esperar que el equipo reorganice las demás tareas según su disponibilidad.", "delegar todas sus funciones del proyecto en los estudiantes mayores, dado que el liderazgo juvenil hace parte de los objetivos de la experiencia."]'::jsonb, 0, 'Informar con anticipación y proponer alternativas permite conciliar responsabilidades sin abandonar los compromisos institucionales.', '["Informar con anticipación y proponer alternativas permite conciliar responsabilidades sin abandonar los compromisos institucionales.", "Priorizar unilateralmente su asignatura traslada el problema al equipo y reduce la corresponsabilidad.", "Los estudiantes pueden apoyar, pero no deben sustituir completamente las responsabilidades profesionales de la docente."]'::jsonb),
    ('elkin-situacion-3', 54, 'elkin-s3-q4', 54, 'La actuación que mejor fortalece el liderazgo institucional de Marcela frente a los estudiantes mentores es:', '["asignarles funciones precisas y supervisar que cumplan estrictamente las instrucciones dadas por los docentes.", "seleccionar únicamente a los estudiantes con mejor comportamiento para reducir la posibilidad de dificultades durante la muestra.", "explicar el propósito del acompañamiento, expresar expectativas positivas, prepararlos y comprometerlos con una responsabilidad común."]'::jsonb, 2, 'Comunicar el propósito, expresar confianza y preparar a los estudiantes evidencia liderazgo y expectativas positivas.', '["Una supervisión rígida garantiza cumplimiento, pero no necesariamente desarrolla liderazgo, autonomía ni sentido institucional.", "Seleccionar únicamente a quienes tienen mejor comportamiento limita las oportunidades formativas de otros estudiantes.", "Comunicar el propósito, expresar confianza y preparar a los estudiantes evidencia liderazgo y expectativas positivas."]'::jsonb),
    ('elkin-situacion-3', 55, 'elkin-s3-q5', 55, 'Para organizar el trabajo entre preescolar, primaria y bachillerato, la estrategia más pertinente es:', '["construir una planeación compartida con responsabilidades claras, aportes de todos los niveles y espacios periódicos de revisión.", "dividir completamente las tareas por niveles para evitar que las diferencias metodológicas generen nuevos conflictos.", "permitir que el docente más organizado centralice las decisiones y consulte al equipo únicamente cuando aparezcan dificultades."]'::jsonb, 0, 'La planeación compartida promueve cooperación, claridad de funciones y seguimiento de los objetivos comunes.', '["La planeación compartida promueve cooperación, claridad de funciones y seguimiento de los objetivos comunes.", "Separar totalmente los niveles mantiene la fragmentación que el proyecto pretende superar.", "Centralizar decisiones en una persona reduce la participación y puede generar dependencia o resistencia."]'::jsonb),
    ('elkin-situacion-3', 56, 'elkin-s3-q6', 56, 'Ante la reducción del presupuesto, la respuesta que evidencia mayor capacidad para transformar la dificultad en una oportunidad es:', '["reducir el número de actividades para asegurar que los recursos disponibles permitan presentar productos de alta calidad.", "solicitar al rector que gestione recursos adicionales antes de continuar, pues avanzar sin presupuesto suficiente puede afectar el resultado institucional.", "reorganizar las propuestas, aprovechar recursos disponibles y establecer alianzas con familias, estudiantes y actores comunitarios."]'::jsonb, 2, 'Reorganizar recursos y crear alianzas evidencia iniciativa, flexibilidad, recursividad y compromiso institucional.', '["Reducir actividades puede ser práctico, pero no refleja por sí mismo iniciativa ni búsqueda de alternativas novedosas.", "Detener el proceso hasta obtener nuevos recursos muestra dependencia y poca capacidad de adaptación.", "Reorganizar recursos y crear alianzas evidencia iniciativa, flexibilidad, recursividad y compromiso institucional."]'::jsonb),
    ('elkin-situacion-3', 57, 'elkin-s3-q7', 57, 'Cuando varias familias reciben información contradictoria sobre horarios y actividades, la institución debería:', '["pedir a cada director de grupo que explique nuevamente la información por el medio que utiliza habitualmente con sus familias.", "reconocer la confusión, unificar los mensajes, definir canales claros y ofrecer información oportuna y comprensible.", "mantener la información ya enviada y publicar una aclaración general para evitar que los cambios afecten la credibilidad institucional."]'::jsonb, 1, 'Reconocer el problema, unificar canales y comunicar claramente fortalece la confianza y la relación con las familias.', '["Mantener canales diferentes puede reproducir la descoordinación y continuar generando mensajes contradictorios.", "Reconocer el problema, unificar canales y comunicar claramente fortalece la confianza y la relación con las familias.", "Mantener información errónea por temor a perder credibilidad prioriza la imagen sobre la solución efectiva."]'::jsonb),
    ('elkin-situacion-3', 58, 'elkin-s3-q8', 58, 'Frente a la inconformidad de la madre que publicó acusaciones en redes sociales, la actuación más adecuada es:', '["responder públicamente con evidencias que demuestren que la institución aplicó criterios objetivos de participación.", "solicitar que elimine primero la publicación y, una vez protegida la imagen institucional, escuchar su inconformidad.", "escucharla en un espacio respetuoso, identificar el origen del problema, revisar las prácticas señaladas y acordar acciones con seguimiento."]'::jsonb, 2, 'Escuchar, revisar las prácticas y acordar soluciones demuestra comunicación asertiva, mediación y compromiso con el mejoramiento.', '["Responder públicamente puede aumentar el conflicto y convertir la situación en una disputa institucional.", "Condicionar la escucha a retirar la publicación impide comprender primero las razones de la inconformidad.", "Escuchar, revisar las prácticas y acordar soluciones demuestra comunicación asertiva, mediación y compromiso con el mejoramiento."]'::jsonb),
    ('elkin-situacion-3', 59, 'elkin-s3-q9', 59, 'Si Laura recibe un mensaje que interpreta como una descalificación de su trabajo, la respuesta más adecuada es:', '["regular su reacción, solicitar una aclaración por un canal apropiado y expresar su desacuerdo de forma respetuosa y concreta.", "responder inmediatamente para evitar que la ausencia de una defensa permita que otros docentes acepten la crítica como verdadera.", "evitar cualquier respuesta y comunicar el asunto al rector para que determine si el mensaje constituye una falta institucional."]'::jsonb, 0, 'Regular la emoción, pedir aclaraciones y expresar el desacuerdo respetuosamente favorece relaciones profesionales basadas en confianza.', '["Regular la emoción, pedir aclaraciones y expresar el desacuerdo respetuosamente favorece relaciones profesionales basadas en confianza.", "Una respuesta inmediata y defensiva puede aumentar la tensión e impedir comprender la intención del mensaje.", "Evitar el diálogo directo y remitir de inmediato al rector dificulta la resolución profesional entre colegas."]'::jsonb),
    ('elkin-situacion-3', 60, 'elkin-s3-q10', 60, 'Al comprobar que las familias de las veredas alejadas participaron poco, la decisión que mejor orienta el trabajo hacia resultados de mayor calidad es:', '["analizar las causas, ajustar las estrategias de convocatoria y establecer una meta verificable para ampliar su participación.", "mantener la estrategia utilizada, pues el aumento general de asistencia demuestra que el propósito institucional fue alcanzado.", "concentrar el siguiente proyecto en las familias que mostraron disposición, evitando invertir recursos en sectores con baja respuesta."]'::jsonb, 0, 'Analizar causas y formular metas verificables expresa orientación al logro y compromiso con el mejoramiento continuo.', '["Analizar causas y formular metas verificables expresa orientación al logro y compromiso con el mejoramiento continuo.", "Conformarse con un aumento general oculta la baja participación de sectores específicos.", "Excluir a las familias con menor participación profundiza las brechas y contradice la finalidad comunitaria."]'::jsonb),
    ('elkin-situacion-3', 61, 'elkin-s3-q11', 61, 'Ante la publicación del video burlón de los niños de preescolar, la respuesta docente más adecuada es:', '["aplicar una sanción al autor principal y pedirle que ofrezca disculpas públicas para que el grupo comprenda la gravedad de la conducta.", "retirar el video y desarrollar una charla general sobre redes sociales, evitando ampliar la exposición de los niños afectados.", "proteger a los niños, intervenir con quienes produjeron y reforzaron la publicación, promover responsabilidad y realizar seguimiento a la reparación."]'::jsonb, 2, 'La actuación articula protección, responsabilidad, intervención pedagógica, reparación y seguimiento.', '["Sancionar al autor principal no aborda a quienes reforzaron la publicación ni garantiza reparación y aprendizaje.", "Una charla general puede ser insuficiente y diluir las responsabilidades individuales y grupales.", "La actuación articula protección, responsabilidad, intervención pedagógica, reparación y seguimiento."]'::jsonb),
    ('elkin-situacion-3', 62, 'elkin-s3-q12', 62, 'Al elaborar el informe final para posibles aliados, la actuación más comprometida con el mejoramiento institucional es:', '["destacar los resultados positivos y reservar las dificultades para la evaluación interna, evitando afectar futuras oportunidades de apoyo.", "presentar únicamente los datos que puedan verificarse mediante fotografías, listas de asistencia y productos elaborados.", "informar con honestidad los logros y las dificultades, explicar las acciones de mejora y asumir responsablemente los compromisos pendientes."]'::jsonb, 2, 'Presentar logros y dificultades con honestidad demuestra compromiso social, integridad y orientación al mejoramiento.', '["Ocultar dificultades protege una imagen momentánea, pero impide aprender y puede comprometer la transparencia institucional.", "Los datos verificables son necesarios, aunque no bastan para explicar procesos, limitaciones y decisiones de mejora.", "Presentar logros y dificultades con honestidad demuestra compromiso social, integridad y orientación al mejoramiento."]'::jsonb),
    ('elkin-situacion-3', 63, 'elkin-s3-q13', 63, 'Durante la formación de los estudiantes mentores, la intervención más pertinente de Marcela es:', '["advertirles que cualquier incumplimiento afectará su valoración de comportamiento y su participación en futuros proyectos.", "modelar el trato esperado, explicar el sentido de la tarea, acompañar sus avances y confiarles responsabilidades progresivas.", "permitir que organicen autónomamente el acompañamiento para que desarrollen liderazgo mediante la experiencia directa."]'::jsonb, 1, 'Modelar, acompañar y otorgar responsabilidades progresivas fortalece liderazgo, comunicación y formación integral.', '["Centrar la formación en amenazas puede producir cumplimiento superficial sin compromiso con el sentido de la tarea.", "Modelar, acompañar y otorgar responsabilidades progresivas fortalece liderazgo, comunicación y formación integral.", "Una autonomía total sin preparación puede exponer a los estudiantes a situaciones que aún no saben manejar."]'::jsonb),
    ('elkin-situacion-3', 64, 'elkin-s3-q14', 64, 'Cuando Laura considera excluir parcialmente a Mateo para evitarle ansiedad, la decisión más adecuada es:', '["mantener su participación limitada, pues el bienestar emocional debe priorizarse sobre los objetivos generales del proyecto.", "anticipar la experiencia, organizar apoyos y permitir que participe de acuerdo con sus posibilidades sin asumir que debe permanecer apartado.", "solicitar a la familia que lo acompañe permanentemente, trasladando a sus cuidadores la responsabilidad de regular cualquier dificultad."]'::jsonb, 1, 'Anticipar, ajustar y ofrecer apoyos permite proteger su bienestar sin impedir su participación.', '["Limitar preventivamente la participación de Mateo puede convertirse en exclusión basada en supuestos.", "Anticipar, ajustar y ofrecer apoyos permite proteger su bienestar sin impedir su participación.", "La familia puede colaborar, pero la institución no debe trasladarle toda la responsabilidad de apoyo."]'::jsonb),
    ('elkin-situacion-3', 65, 'elkin-s3-q15', 65, 'Después de que Marcela le señala a Daniel que monopoliza las reuniones, la actuación más constructiva de este es:', '["explicar que su intervención extensa responde a la necesidad de garantizar que el equipo cumpla con los compromisos.", "revisar su actuación, escuchar la observación y modificar la dinámica para favorecer la participación y el liderazgo compartido.", "pedir que las observaciones futuras sean presentadas únicamente en las reuniones formales para evitar cuestionamientos personales."]'::jsonb, 1, 'Escuchar, autorregularse y modificar las reuniones evidencia apertura a la crítica y disposición para el trabajo en equipo.', '["Justificar su conducta sin revisar los efectos reduce la posibilidad de aprendizaje profesional.", "Escuchar, autorregularse y modificar las reuniones evidencia apertura a la crítica y disposición para el trabajo en equipo.", "Limitar las observaciones a espacios formales puede obstaculizar una comunicación profesional oportuna."]'::jsonb),
    ('elkin-situacion-3', 66, 'elkin-s3-q16', 66, 'Cuando dos niveles solicitan el mismo espacio y los mismos equipos, el procedimiento más adecuado consiste en:', '["asignar los recursos al nivel que presente productos con mayor impacto para la imagen institucional.", "distribuir los recursos en partes iguales, aunque algunas actividades requieran condiciones diferentes.", "identificar las necesidades reales, acordar criterios transparentes, priorizar los propósitos comunes y verificar el cumplimiento del acuerdo."]'::jsonb, 2, 'Negociar con criterios transparentes y verificar acuerdos demuestra mediación y orientación hacia intereses comunes.', '["Priorizar la imagen institucional puede desconocer necesidades pedagógicas y criterios de equidad.", "Una distribución idéntica no siempre es justa cuando las actividades tienen necesidades diferentes.", "Negociar con criterios transparentes y verificar acuerdos demuestra mediación y orientación hacia intereses comunes."]'::jsonb),
    ('elkin-situacion-3', 67, 'elkin-s3-q17', 67, 'Ante la incapacidad médica de Laura, la actuación más adecuada del equipo es:', '["cancelar temporalmente la participación de preescolar, pues continuar sin su docente puede afectar la seguridad y la calidad del proceso.", "redistribuir provisionalmente las tareas, compartir recursos y sostener el proceso sin convertir el apoyo temporal en una sobrecarga permanente.", "solicitar a Laura que oriente virtualmente a sus compañeros, dado que su conocimiento del grupo resulta indispensable para continuar."]'::jsonb, 1, 'La redistribución temporal permite sostener el proceso mediante cooperación sin normalizar la sobrecarga.', '["Cancelar la participación desconoce la posibilidad de colaboración y afecta innecesariamente a los estudiantes.", "La redistribución temporal permite sostener el proceso mediante cooperación sin normalizar la sobrecarga.", "Solicitar trabajo durante una incapacidad desconoce el bienestar y los derechos laborales de Laura."]'::jsonb),
    ('elkin-situacion-3', 68, 'elkin-s3-q18', 68, 'Si varios estudiantes de bachillerato abandonan sus responsabilidades de acompañamiento durante el evento, la respuesta posterior más pertinente es:', '["excluirlos de futuras actividades institucionales para mostrar que el incumplimiento tiene consecuencias claras.", "registrar la falta, informar a las familias y asignar una actividad escrita sobre responsabilidad.", "analizar con ellos las causas, relacionar su actuación con el propósito común, reconstruir compromisos y hacer seguimiento a cambios observables."]'::jsonb, 2, 'Analizar causas, reconstruir compromisos y hacer seguimiento convierte el incumplimiento en una experiencia formativa.', '["Excluirlos de futuros proyectos puede cerrar oportunidades de aprendizaje y reparación.", "Registrar la falta y asignar un escrito no garantiza comprensión ni cambio observable.", "Analizar causas, reconstruir compromisos y hacer seguimiento convierte el incumplimiento en una experiencia formativa."]'::jsonb),
    ('elkin-situacion-3', 69, 'elkin-s3-q19', 69, 'Antes de publicar imágenes del proyecto en redes institucionales, los docentes deben:', '["verificar las autorizaciones, aplicar los procedimientos institucionales y evitar exponer información innecesaria de los estudiantes.", "utilizar solo fotografías grupales, porque estas no permiten identificar responsabilidades ni desempeños individuales.", "publicar las imágenes más representativas y retirarlas posteriormente si alguna familia manifiesta inconformidad."]'::jsonb, 0, 'Verificar autorizaciones y limitar la exposición protege la privacidad y demuestra responsabilidad institucional.', '["Verificar autorizaciones y limitar la exposición protege la privacidad y demuestra responsabilidad institucional.", "Las fotografías grupales también pueden permitir la identificación de estudiantes y requieren autorización.", "Publicar primero y retirar después desconoce la prevención y puede producir daños difíciles de revertir."]'::jsonb),
    ('elkin-situacion-3', 70, 'elkin-s3-q20', 70, 'Ante el anuncio de fuertes lluvias, la respuesta más adecuada del equipo es:', '["mantener la programación original hasta confirmar que las condiciones climáticas realmente impidan realizar las actividades.", "aplazar completamente el evento para conservar la calidad de todas las actividades previamente organizadas.", "activar el plan alternativo, reorganizar espacios y responsabilidades, comunicar los cambios y proteger la seguridad sin perder los propósitos centrales."]'::jsonb, 2, 'Adaptar la programación preservando la seguridad y los objetivos demuestra iniciativa, flexibilidad y orientación al logro.', '["Esperar hasta confirmar el riesgo puede dejar al equipo sin tiempo para proteger a los participantes.", "Aplazar completamente puede ser innecesario si existen alternativas seguras y viables.", "Adaptar la programación preservando la seguridad y los objetivos demuestra iniciativa, flexibilidad y orientación al logro."]'::jsonb),
    ('elkin-situacion-3', 71, 'elkin-s3-q21', 71, 'Después de la muestra institucional, la actuación que mejor evidencia orientación hacia el mejoramiento continuo es:', '["comparar los resultados con las metas, reconocer las brechas y establecer acciones medibles para superar las dificultades identificadas.", "conservar las actividades que recibieron mayor aceptación y eliminar aquellas que presentaron problemas logísticos.", "valorar principalmente la percepción positiva de los asistentes, pues los proyectos institucionales deben fortalecer la motivación comunitaria."]'::jsonb, 0, 'Comparar metas, reconocer brechas y formular acciones medibles permite mejorar sistemáticamente.', '["Comparar metas, reconocer brechas y formular acciones medibles permite mejorar sistemáticamente.", "Eliminar actividades problemáticas sin analizar las causas puede impedir aprendizajes y mejoras futuras.", "La percepción positiva es valiosa, pero no sustituye la evaluación de resultados, dificultades y metas."]'::jsonb),
    ('elkin-situacion-3', 72, 'elkin-s3-q22', 72, 'Si Marcela propone una nueva estrategia de pódcast que no estaba incluida en la planeación inicial, la actuación más adecuada es:', '["desarrollarla directamente con sus estudiantes para demostrar su viabilidad antes de solicitar cambios institucionales.", "esperar al siguiente año para evitar que una innovación modifique responsabilidades ya acordadas.", "analizar su coherencia con los objetivos, coordinarla con el equipo y ponerla en práctica de manera organizada y responsable."]'::jsonb, 2, 'Analizar pertinencia, coordinar y ejecutar responsablemente evidencia iniciativa articulada con los objetivos institucionales.', '["Implementar unilateralmente la idea puede generar desarticulación y afectar compromisos previamente acordados.", "Aplazar automáticamente la innovación desconoce la posibilidad de mejorar el proyecto actual.", "Analizar pertinencia, coordinar y ejecutar responsablemente evidencia iniciativa articulada con los objetivos institucionales."]'::jsonb),
    ('elkin-situacion-3', 73, 'elkin-s3-q23', 73, 'Ante la tensión entre la preparación académica de bachillerato y la participación en el proyecto institucional, la decisión más adecuada es:', '["priorizar la preparación para evaluaciones externas, pues sus resultados tienen mayor incidencia en las metas institucionales.", "articular los aprendizajes curriculares con las actividades del proyecto, evitando tanto el abandono académico como la sobrecarga.", "distribuir el tiempo en partes iguales entre ambas responsabilidades, independientemente de las necesidades específicas de cada grupo."]'::jsonb, 1, 'Articular el currículo con la experiencia institucional permite cumplir ambos propósitos sin generar sobrecarga innecesaria.', '["Priorizar exclusivamente evaluaciones externas desconoce los aprendizajes y competencias desarrollados en el proyecto.", "Articular el currículo con la experiencia institucional permite cumplir ambos propósitos sin generar sobrecarga innecesaria.", "Dividir el tiempo por partes iguales no considera las necesidades ni prioridades reales de cada momento."]'::jsonb),
    ('elkin-situacion-3', 74, 'elkin-s3-q24', 74, 'Cuando Daniel descubre que una decisión suya generó retrasos en el equipo, la actuación que mejor fortalece la confianza es:', '["reconocer su responsabilidad, explicar lo ocurrido sin trasladar culpas y participar activamente en la corrección del problema.", "compensar el retraso trabajando por su cuenta hasta cumplir la meta, sin ampliar una situación que puede afectar la imagen del equipo.", "informar que la decisión fue tomada para beneficiar el proyecto y solicitar que el equipo se concentre en las soluciones futuras."]'::jsonb, 0, 'Reconocer el error y participar en la solución fortalece la confianza, la responsabilidad y el compromiso con el equipo.', '["Reconocer el error y participar en la solución fortalece la confianza, la responsabilidad y el compromiso con el equipo.", "Solucionar en silencio puede ocultar información necesaria y no reconstruye la confianza afectada.", "Justificar la intención no elimina la responsabilidad por los efectos de la decisión."]'::jsonb),
    ('elkin-situacion-3', 75, 'elkin-s3-q25', 75, 'Ante el conjunto de dificultades presentadas, la actuación profesional más completa del equipo docente sería:', '["establecer una coordinación central fuerte que distribuya funciones, controle los resultados y reduzca la posibilidad de desacuerdos.", "construir una visión común, comunicarse con respeto, colaborar, mediar los conflictos, actuar con iniciativa, cumplir los compromisos y evaluar continuamente los resultados.", "permitir que cada nivel conserve autonomía plena, reuniéndose únicamente cuando existan problemas que afecten a toda la institución."]'::jsonb, 1, 'Integra liderazgo, comunicación, trabajo en equipo, mediación, iniciativa, compromiso y orientación al logro.', '["Una dirección excesivamente centralizada reduce participación, autonomía y corresponsabilidad.", "Integra liderazgo, comunicación, trabajo en equipo, mediación, iniciativa, compromiso y orientación al logro.", "La autonomía aislada mantiene la fragmentación y dificulta la construcción de metas institucionales comunes."]'::jsonb),
    ('elkin-situacion-4', 1, 'elkin-s4-q1', 76, 'Al comparar los resultados de lectura inferencial de quinto A y quinto B, el grupo que presenta la mayor proporción de estudiantes en desempeño bajo es:', '["Quinto A, porque tiene doce estudiantes en desempeño bajo, mientras que quinto B tiene nueve.", "Quinto B, porque nueve estudiantes representan una parte mayor de veinte que doce estudiantes de un grupo de treinta.", "Los dos grupos, porque la diferencia de tres estudiantes se compensa con la diferencia en el tamaño de los cursos."]'::jsonb, 1, 'Nueve de veinte representa una proporción mayor que doce de treinta, aunque el número absoluto sea menor.', '["Compara únicamente cantidades absolutas y no considera que los grupos tienen tamaños diferentes.", "Nueve de veinte representa una proporción mayor que doce de treinta, aunque el número absoluto sea menor.", "Las diferencias en matrícula no compensan automáticamente las cantidades; es necesario comparar la relación dentro de cada grupo."]'::jsonb),
    ('elkin-situacion-4', 2, 'elkin-s4-q2', 77, 'Respecto a los resultados de lectura de séptimo A y séptimo B, la interpretación más adecuada es:', '["Séptimo A requiere mayor prioridad porque tiene cuatro estudiantes más en desempeño bajo que séptimo", "B. Los dos grupos presentan una necesidad equivalente porque en ambos el número de estudiantes con dificultad se aproxima a la mitad del curso.", "Séptimo B presenta una proporción ligeramente mayor de estudiantes en desempeño bajo, aunque séptimo A tenga una cantidad absoluta superior."]'::jsonb, 2, 'Once de veinticuatro representa una proporción ligeramente mayor que quince de treinta y seis.', '["Tener más estudiantes en dificultad no significa necesariamente presentar la mayor necesidad proporcional.", "Las proporciones son cercanas, pero no equivalentes, y deben analizarse con precisión.", "Once de veinticuatro representa una proporción ligeramente mayor que quince de treinta y seis."]'::jsonb),
    ('elkin-situacion-4', 3, 'elkin-s4-q3', 78, 'Al comparar la interpretación cuantitativa de noveno A y noveno B, el grupo con la necesidad proporcionalmente mayor es:', '["Noveno B, porque diez de sus veintiocho estudiantes están en desempeño bajo.", "Noveno A, porque trece de sus treinta y dos estudiantes representan una proporción mayor que diez de veintiocho.", "Ambos grupos, porque la diferencia en número de estudiantes es semejante a la diferencia en sus matrículas."]'::jsonb, 1, 'Trece de treinta y dos representa una parte mayor del grupo que diez de veintiocho.', '["Noveno B presenta una proporción importante, pero es inferior a la de noveno A.", "Trece de treinta y dos representa una parte mayor del grupo que diez de veintiocho.", "La semejanza entre las diferencias absolutas no permite concluir que las proporciones sean iguales."]'::jsonb),
    ('elkin-situacion-4', 4, 'elkin-s4-q4', 79, 'El objetivo que responde de manera más pertinente al diagnóstico institucional es:', '["Fortalecer la interpretación de relaciones implícitas, la justificación con evidencias y el análisis de información cuantitativa, estableciendo metas según las necesidades de cada grupo.", "Mejorar las notas de Lengua Castellana y Matemáticas mediante talleres adicionales que puedan aplicarse de la misma manera en todos los cursos.", "Desarrollar actividades motivadoras de lectura y cálculo que permitan aumentar la participación de los estudiantes durante las seis semanas."]'::jsonb, 0, 'El objetivo define aprendizajes concretos, se relaciona con el diagnóstico y permite establecer metas diferenciadas.', '["El objetivo define aprendizajes concretos, se relaciona con el diagnóstico y permite establecer metas diferenciadas.", "Se centra en las notas y en talleres uniformes, sin precisar las competencias que deben fortalecerse.", "La motivación y la participación son importantes, pero el objetivo no define claramente los aprendizajes esperados."]'::jsonb),
    ('elkin-situacion-4', 5, 'elkin-s4-q5', 80, 'La afirmación del rector según la cual noveno no requiere apoyo prioritario porque cada grupo tiene solamente ocho estudiantes con desempeño bajo en lectura es:', '["adecuada, porque quinto y séptimo reúnen una cantidad mayor de estudiantes con dificultades y deben recibir primero los recursos.", "insuficiente, porque debe considerarse la proporción dentro de cada grupo, las demás competencias evaluadas y las necesidades específicas de los estudiantes.", "válida únicamente para noveno A, debido a que su número total de estudiantes es mayor que el de noveno B."]'::jsonb, 1, 'Se deben considerar proporciones, competencias diferentes y condiciones específicas antes de determinar prioridades.', '["Priorizar solo por cantidad absoluta puede producir decisiones inequitativas y omitir otras necesidades.", "Se deben considerar proporciones, competencias diferentes y condiciones específicas antes de determinar prioridades.", "La afirmación tampoco es válida automáticamente para noveno A, pues el análisis debe ser integral."]'::jsonb),
    ('elkin-situacion-4', 6, 'elkin-s4-q6', 81, 'Si el primer ciclo intensivo debe comenzar con los dos grupos que presentan las mayores proporciones de bajo desempeño en lectura, la decisión más pertinente es:', '["iniciar con séptimo B y quinto B, sin excluir que los demás grupos reciban posteriormente otras acciones de apoyo.", "comenzar con séptimo A y quinto A, porque juntos reúnen la mayor cantidad de estudiantes en desempeño bajo.", "seleccionar quinto A y séptimo B, porque combinan una alta cantidad absoluta con una alta proporción de estudiantes con dificultades."]'::jsonb, 0, 'Quinto B y séptimo B presentan las mayores proporciones de estudiantes con desempeño bajo en lectura.', '["Quinto B y séptimo B presentan las mayores proporciones de estudiantes con desempeño bajo en lectura.", "Selecciona los grupos con mayor cantidad absoluta, pero no con mayor proporción.", "Combina criterios distintos sin responder exactamente a la condición planteada en la pregunta."]'::jsonb),
    ('elkin-situacion-4', 7, 'elkin-s4-q7', 82, 'A partir del dato según el cual cuarenta y ocho de los sesenta participantes mejoraron por lo menos un criterio, puede afirmarse válidamente que:', '["la mayoría de los participantes presentó algún avance, pero ese resultado no demuestra por sí solo que el proyecto haya sido la única causa.", "el proyecto fue eficaz para todos los estudiantes, aunque doce participantes permanecieran en el mismo nivel.", "la intervención produjo directamente la mejora porque la cantidad de estudiantes que avanzó fue claramente superior a la que no avanzó."]'::jsonb, 0, 'Los datos permiten afirmar que la mayoría avanzó, pero no demostrar causalidad exclusiva.', '["Los datos permiten afirmar que la mayoría avanzó, pero no demostrar causalidad exclusiva.", "Doce estudiantes no mejoraron, por lo que no puede sostenerse que el proyecto fue eficaz para todos.", "Una diferencia entre quienes mejoraron y quienes no mejoraron no prueba por sí misma que el proyecto causó el avance."]'::jsonb),
    ('elkin-situacion-4', 8, 'elkin-s4-q8', 83, 'La conclusión de que todos los estudiantes aprenden mejor mediante videos es inadecuada porque:', '["la encuesta muestra una preferencia mayoritaria, pero no unanimidad ni evidencia suficiente sobre cuál estrategia produce mejores aprendizajes.", "los estudiantes que prefieren videos pueden estar interesados principalmente en actividades recreativas y no en desarrollar competencias.", "una encuesta de percepción solo puede utilizarse cuando todos los estudiantes del colegio responden las mismas preguntas."]'::jsonb, 0, 'La encuesta mide preferencias y muestra diversidad; no demuestra cuál estrategia produce más aprendizaje.', '["La encuesta mide preferencias y muestra diversidad; no demuestra cuál estrategia produce más aprendizaje.", "Atribuye intenciones recreativas sin evidencia y descalifica injustificadamente la opinión estudiantil.", "Una encuesta puede utilizarse con una muestra definida si se interpretan adecuadamente sus límites."]'::jsonb),
    ('elkin-situacion-4', 9, 'elkin-s4-q9', 84, 'Antes de publicar que el número de estudiantes con desempeño bajo se redujo de veinticuatro a doce, la institución debe:', '["calcular el promedio entre las dos cifras para comunicar un resultado menos extremo y más comprensible.", "mantener la afirmación, pero aclarar que algunos estudiantes no presentaron la prueba final.", "comprobar que las cifras correspondan a grupos comparables e incluir a quienes no tienen información final antes de concluir que la reducción fue de la mitad."]'::jsonb, 2, 'Deben compararse los mismos estudiantes o explicar claramente la ausencia de información antes de afirmar una reducción.', '["Promediar cifras no resuelve la falta de comparabilidad entre los estudiantes evaluados en ambos momentos.", "Mantener la afirmación seguiría presentando como comparable una información incompleta.", "Deben compararse los mismos estudiantes o explicar claramente la ausencia de información antes de afirmar una reducción."]'::jsonb),
    ('elkin-situacion-4', 10, 'elkin-s4-q10', 85, 'El testimonio del estudiante que atribuye su mejor nota a que el texto final era más corto y las preguntas más directas permite concluir que:', '["el estudiante desarrolló estrategias de lectura que le permitieron resolver con mayor rapidez una evaluación más accesible.", "la evaluación final fue adecuada porque permitió que el estudiante expresara sus aprendizajes sin enfrentar textos innecesariamente extensos.", "la mejora en la calificación puede estar relacionada con diferencias en la dificultad de las pruebas y no demuestra por sí sola una comprensión más profunda."]'::jsonb, 2, 'La mejor nota puede explicarse por una prueba menos exigente, por lo que el testimonio no prueba avance por sí solo.', '["El testimonio no demuestra que haya desarrollado estrategias de lectura más profundas.", "Que la prueba fuera más accesible no permite concluir que evaluara con igual complejidad las competencias iniciales.", "La mejor nota puede explicarse por una prueba menos exigente, por lo que el testimonio no prueba avance por sí solo."]'::jsonb),
    ('elkin-situacion-4', 11, 'elkin-s4-q11', 86, 'La secuencia de planeación más coherente para el proyecto es:', '["seleccionar actividades, distribuir materiales, aplicar la evaluación, revisar resultados y formular posteriormente los objetivos.", "analizar el diagnóstico, definir aprendizajes y metas, seleccionar estrategias, asignar recursos y responsabilidades, y establecer seguimiento.", "distribuir responsabilidades, aplicar talleres iniciales, identificar dificultades durante la práctica y formular metas según los resultados."]'::jsonb, 1, 'Parte del diagnóstico, define metas y estrategias, organiza recursos y establece seguimiento.', '["Formular objetivos después de aplicar actividades invierte la lógica de una planeación coherente.", "Parte del diagnóstico, define metas y estrategias, organiza recursos y establece seguimiento.", "Comenzar talleres antes de precisar metas puede producir actividades desarticuladas de las necesidades reales."]'::jsonb),
    ('elkin-situacion-4', 12, 'elkin-s4-q12', 87, 'El indicador más pertinente para verificar si los estudiantes mejoraron en la justificación de conclusiones sería:', '["la cantidad de talleres desarrollados y entregados durante las seis semanas del proyecto.", "la proporción de estudiantes que formula una conclusión y la sustenta con evidencias pertinentes tomadas del texto o la situación.", "el aumento del promedio general en las asignaturas de Lengua Castellana y Matemáticas."]'::jsonb, 1, 'Permite observar si los estudiantes elaboran conclusiones y las respaldan con evidencias pertinentes.', '["La cantidad de talleres mide ejecución, pero no demuestra mejoramiento en la competencia.", "Permite observar si los estudiantes elaboran conclusiones y las respaldan con evidencias pertinentes.", "Un promedio general puede aumentar por múltiples razones y no mide específicamente la justificación."]'::jsonb),
    ('elkin-situacion-4', 13, 'elkin-s4-q13', 88, 'Frente a la disponibilidad de dieciocho tabletas para grupos con más de veinte estudiantes, la estrategia más adecuada es:', '["reservar los dispositivos para quienes presentan desempeño bajo y asignar actividades impresas a los demás estudiantes.", "entregar las tabletas a los estudiantes con mejores resultados para que orienten al resto del curso durante toda la actividad.", "organizar estaciones y rotaciones en las que todos puedan usar los dispositivos y desarrollar las mismas competencias mediante distintos recursos."]'::jsonb, 2, 'Las estaciones permiten distribuir recursos escasos y garantizar participación de todo el grupo.', '["Reservar los dispositivos para un grupo restringe la participación y puede generar segregación.", "Entregarlos siempre a los estudiantes con mejores resultados limita el acceso de los demás.", "Las estaciones permiten distribuir recursos escasos y garantizar participación de todo el grupo."]'::jsonb),
    ('elkin-situacion-4', 14, 'elkin-s4-q14', 89, 'La principal dificultad de la planeación que propone inferir la intención del autor, pero se limita a copiar y relacionar definiciones, es que:', '["utiliza actividades demasiado sencillas para los grados seleccionados y debería incluir textos de mayor extensión.", "las actividades y la evaluación no permiten demostrar el aprendizaje formulado en el propósito de la clase.", "la memorización de conceptos debe realizarse después del análisis de textos y no antes de presentar la evaluación."]'::jsonb, 1, 'Copiar definiciones no demuestra que el estudiante infiera intenciones ni valore argumentos.', '["El problema central no es la extensión o dificultad de las actividades, sino su falta de alineación.", "Copiar definiciones no demuestra que el estudiante infiera intenciones ni valore argumentos.", "Cambiar el orden de memorización y análisis no resolvería necesariamente la falta de correspondencia evaluativa."]'::jsonb),
    ('elkin-situacion-4', 15, 'elkin-s4-q15', 90, 'Al comparar la disminución del desempeño bajo en quinto B, séptimo B y noveno A, el grupo que presentó el mayor cambio respecto a su punto de partida fue:', '["Séptimo B, porque disminuyó tres estudiantes y comenzó con la cantidad inicial más alta.", "Noveno A, porque terminó con el menor número de estudiantes en desempeño bajo.", "Quinto B, porque una reducción de tres estudiantes representa una parte mayor de los nueve con los que comenzó."]'::jsonb, 2, 'Reducir tres de nueve representa una proporción mayor que reducir tres de once o uno de ocho.', '["Séptimo B redujo tres estudiantes, pero partía de once, por lo que el cambio proporcional es menor.", "Terminar con el número más bajo no significa haber presentado el mayor cambio relativo.", "Reducir tres de nueve representa una proporción mayor que reducir tres de once o uno de ocho."]'::jsonb),
    ('elkin-situacion-4', 16, 'elkin-s4-q16', 91, 'La afirmación de que quinto B y séptimo B mejoraron en la misma proporción porque ambos redujeron tres estudiantes es:', '["inadecuada, porque la misma disminución absoluta representa cambios diferentes cuando los grupos parten de cantidades distintas.", "correcta, porque el número de estudiantes que salió del desempeño bajo fue idéntico en los dos grupos.", "válida solamente si los dos cursos participaron en la misma cantidad de sesiones y desarrollaron actividades equivalentes."]'::jsonb, 0, 'La misma disminución absoluta representa cambios diferentes cuando los valores iniciales no son iguales.', '["La misma disminución absoluta representa cambios diferentes cuando los valores iniciales no son iguales.", "Compara solo la cantidad reducida y desconoce el punto de partida.", "La asistencia puede ayudar a interpretar los resultados, pero no hace iguales las proporciones."]'::jsonb),
    ('elkin-situacion-4', 17, 'elkin-s4-q17', 92, 'Ante los resultados y las diferencias de asistencia de quinto B y séptimo B, la decisión pedagógica más adecuada es:', '["aplicar nuevas actividades idénticas en los dos grupos para comprobar si las diferencias desaparecen en el siguiente ciclo.", "trasladar los recursos de séptimo B a quinto B, porque el segundo grupo mostró mejores condiciones para aprovechar la intervención.", "consolidar los avances en quinto B y fortalecer en séptimo B las estrategias de asistencia, acompañamiento y eliminación de barreras."]'::jsonb, 2, 'La decisión diferencia acciones según los avances de quinto B y las dificultades de asistencia de séptimo B.', '["Aplicar exactamente lo mismo desconoce que los grupos enfrentan condiciones y necesidades diferentes.", "Retirar apoyos a séptimo B agravaría las barreras que afectan su participación.", "La decisión diferencia acciones según los avances de quinto B y las dificultades de asistencia de séptimo B."]'::jsonb),
    ('elkin-situacion-4', 18, 'elkin-s4-q18', 93, 'El hecho de que una proporción mayor de participantes haya mejorado frente a los estudiantes que no asistieron regularmente permite afirmar que:', '["el proyecto produjo la diferencia, porque quienes participaron obtuvieron mejores resultados que quienes no lo hicieron.", "existe una asociación favorable, pero las diferencias de asistencia y acompañamiento impiden atribuir todo el cambio únicamente al proyecto.", "los estudiantes que no participaron deben incorporarse obligatoriamente, pues sus resultados demuestran que el trabajo ordinario no genera avances suficientes."]'::jsonb, 1, 'Los resultados sugieren una relación positiva, pero la asistencia y el acompañamiento familiar también pudieron influir.', '["La diferencia favorable no prueba causalidad porque los grupos no tenían condiciones equivalentes.", "Los resultados sugieren una relación positiva, pero la asistencia y el acompañamiento familiar también pudieron influir.", "Los datos no demuestran que el trabajo ordinario sea incapaz de generar mejoras."]'::jsonb),
    ('elkin-situacion-4', 19, 'elkin-s4-q19', 94, 'La intención principal del mensaje enviado por la madre de familia es:', '["rechazar la cantidad de actividades asignadas y solicitar que el acompañamiento sea suspendido temporalmente.", "cuestionar la capacidad de los docentes para organizar el proyecto y exigir que las familias participen en la planeación académica.", "solicitar una comunicación coordinada, comprensible y coherente que permita a las familias apoyar el proceso."]'::jsonb, 2, 'Solicita mensajes coherentes, fechas claras y condiciones que permitan acompañar a los estudiantes.', '["La madre afirma expresamente que no rechaza el acompañamiento.", "No exige participar en la planeación académica ni cuestiona globalmente la capacidad docente.", "Solicita mensajes coherentes, fechas claras y condiciones que permitan acompañar a los estudiantes."]'::jsonb),
    ('elkin-situacion-4', 20, 'elkin-s4-q20', 95, 'La respuesta institucional más pertinente frente a la preocupación expresada por las familias es:', '["unificar el canal y el mensaje semanal, aclarar propósitos y fechas, y ofrecer espacios de orientación cuando sean necesarios.", "permitir que cada docente conserve su medio de comunicación, pero exigir que todos envíen la información el mismo día.", "reducir la comunicación con las familias y enviar únicamente un informe al terminar cada ciclo para evitar contradicciones."]'::jsonb, 0, 'Unificar la comunicación y ofrecer orientación responde directamente a la dificultad identificada por las familias.', '["Unificar la comunicación y ofrecer orientación responde directamente a la dificultad identificada por las familias.", "Mantener múltiples canales puede continuar generando versiones diferentes de la misma información.", "Reducir la comunicación impediría el acompañamiento oportuno durante el proceso."]'::jsonb),
    ('elkin-situacion-4', 21, 'elkin-s4-q21', 96, 'Si cuatro docentes pueden realizar seis entrevistas semanales cada uno, el tiempo mínimo para atender a los setenta y dos estudiantes, utilizando todos los espacios disponibles, es:', '["tres semanas.", "cuatro semanas.", "seis semanas."]'::jsonb, 0, 'Entre los cuatro docentes pueden realizar veinticuatro entrevistas por semana; en tres semanas completarían las setenta y dos.', '["Entre los cuatro docentes pueden realizar veinticuatro entrevistas por semana; en tres semanas completarían las setenta y dos.", "Cuatro semanas serían necesarias solo si no se utilizaran completamente los espacios disponibles.", "Seis semanas duplica el tiempo requerido según la capacidad semanal descrita."]'::jsonb),
    ('elkin-situacion-4', 22, 'elkin-s4-q22', 97, 'Aunque el promedio general aumentó de 3,1 a 3,5, los estudiantes inicialmente ubicados en desempeño alto avanzaron más que quienes estaban en desempeño bajo. Esto indica que:', '["el proyecto fue exitoso, porque cualquier aumento del promedio demuestra que las estrategias beneficiaron al conjunto de estudiantes.", "los estudiantes con desempeño bajo necesitan más tiempo, pero la diferencia entre grupos no afecta la valoración general del proyecto.", "el promedio general puede ocultar avances desiguales y una ampliación de las brechas entre los estudiantes."]'::jsonb, 2, 'El promedio puede mejorar mientras los estudiantes con resultados bajos avanzan menos que los de desempeño alto.', '["El aumento del promedio no garantiza que todos los grupos hayan sido beneficiados de manera semejante.", "La ampliación de la distancia sí afecta la valoración, porque muestra una posible profundización de las brechas.", "El promedio puede mejorar mientras los estudiantes con resultados bajos avanzan menos que los de desempeño alto."]'::jsonb),
    ('elkin-situacion-4', 23, 'elkin-s4-q23', 98, 'Para comunicar los resultados de manera más rigurosa, el informe debería:', '["presentar únicamente el promedio institucional, porque permite comparar fácilmente el desempeño entre dos momentos.", "incluir cantidades, porcentajes, número de estudiantes evaluados, cambios por grupo e información faltante.", "seleccionar los datos más favorables y explicar en un apartado final las limitaciones encontradas durante la aplicación."]'::jsonb, 1, 'Una comunicación rigurosa incluye cantidades, proporciones, participantes, cambios por grupo y limitaciones de la información.', '["El promedio único oculta distribuciones, diferencias entre grupos y ausencia de datos.", "Una comunicación rigurosa incluye cantidades, proporciones, participantes, cambios por grupo y limitaciones de la información.", "Seleccionar primero los resultados favorables puede producir una presentación sesgada."]'::jsonb),
    ('elkin-situacion-4', 24, 'elkin-s4-q24', 99, 'Ante la reducción del presupuesto, la decisión de planeación más adecuada es:', '["reducir todas las actividades en la misma proporción para que ningún componente del proyecto reciba un trato preferente.", "proteger las acciones relacionadas con los objetivos, los grupos prioritarios y el seguimiento, reduciendo gastos no esenciales.", "suspender la segunda fase hasta contar con los recursos previstos, pues cambiar las actividades impediría comparar los resultados."]'::jsonb, 1, 'La planeación debe proteger objetivos, grupos prioritarios, acompañamiento y seguimiento, reduciendo lo no indispensable.', '["Reducir todo por igual puede afectar componentes esenciales y conservar gastos poco relevantes.", "La planeación debe proteger objetivos, grupos prioritarios, acompañamiento y seguimiento, reduciendo lo no indispensable.", "Suspender completamente desconoce la posibilidad de adaptar el proyecto a los recursos disponibles."]'::jsonb),
    ('elkin-situacion-4', 25, 'elkin-s4-q25', 100, 'La decisión institucional que integra de manera más rigurosa el análisis de datos, la interpretación crítica y la planeación es:', '["declarar exitoso el proyecto porque la mayoría mejoró, mantener las actividades y aumentar su cobertura durante el siguiente año.", "conservar las estrategias con mejores promedios, retirar las que tuvieron menor aceptación y establecer una meta general para todos los cursos.", "comparar datos equivalentes, reconocer límites y diferencias entre grupos, interpretar críticamente testimonios y afirmaciones, ajustar las estrategias y establecer metas e indicadores diferenciados."]'::jsonb, 2, 'Integra comparación rigurosa, lectura crítica de evidencias, reconocimiento de límites y ajuste de la planeación con metas diferenciadas.', '["Declarar éxito solo por la mejora mayoritaria ignora las limitaciones, diferencias y brechas identificadas.", "Conservar únicamente estrategias con mejores promedios puede desconocer la calidad de los datos y las condiciones de cada grupo.", "Integra comparación rigurosa, lectura crítica de evidencias, reconocimiento de límites y ajuste de la planeación con metas diferenciadas."]'::jsonb)
)
insert into public.quiz_questions (
  external_id,
  test_id,
  test_title,
  category,
  block_id,
  block_range,
  topic,
  situation,
  question_number,
  prompt,
  options,
  correct_answer,
  explanation,
  option_feedback,
  sequence,
  active
)
select
  new_questions.external_id,
  'elkin-simulacro-100',
  'Simulacro de 100 preguntas - El Profe Elkin',
  blocks.category,
  blocks.block_id,
  blocks.block_range,
  blocks.topic,
  blocks.situation,
  new_questions.question_number,
  new_questions.prompt,
  new_questions.options,
  new_questions.correct_answer,
  new_questions.explanation,
  new_questions.option_feedback,
  coalesce(base_sequences.value, 0) + new_questions.category_position,
  true
from new_questions
join blocks using (block_id)
left join base_sequences using (category)
on conflict (external_id) do update set
  test_id = excluded.test_id,
  test_title = excluded.test_title,
  category = excluded.category,
  block_id = excluded.block_id,
  block_range = excluded.block_range,
  topic = excluded.topic,
  situation = excluded.situation,
  question_number = excluded.question_number,
  prompt = excluded.prompt,
  options = excluded.options,
  correct_answer = excluded.correct_answer,
  explanation = excluded.explanation,
  option_feedback = excluded.option_feedback,
  sequence = excluded.sequence,
  active = true;
